import type { ImportedContentSourceFile } from '../librarySources';

export const strixhaven_a_curriculum_of_chaos_source: ImportedContentSourceFile = JSON.parse("{\"schemaVersion\":\"ddbcc-v1\",\"sourceId\":\"strixhaven\",\"label\":\"Strixhaven: A Curriculum of Chaos\",\"category\":\"expansion\",\"aliases\":[],\"description\":\"Imported from 5etools data (source SCC).\",\"content\":{\"species\":[{\"id\":\"strixhaven-owlin\",\"name\":\"Owlin\",\"description\":\"Distant kin of giant owls from the Feywild, owlin come in many shapes and sizes, from petite and fluffy to wide-winged and majestic. Owlin have arms and legs like other Humanoids, as well as wings that extend from their back and shoulders. Like owls, owlin are graced with feathers that make no sound when they move or fly, making it easy for them to sneak up on you in the library.\",\"size\":\"Small\",\"sizeOptions\":[\"Small\",\"Medium\"],\"speed\":30,\"abilityScoreIncreases\":[],\"features\":[{\"id\":\"strixhaven-owlin-size-0\",\"name\":\"Size\",\"description\":\"You are Medium or Small. You choose the size when you select this race.\",\"level\":1,\"source\":\"Strixhaven: A Curriculum of Chaos\"},{\"id\":\"strixhaven-owlin-darkvision-1\",\"name\":\"Darkvision\",\"description\":\"You can see in dim light within 120 feet of yourself as if it were bright light and in darkness as if it were dim light. You discern colors in that darkness only as shades of gray.\",\"level\":1,\"source\":\"Strixhaven: A Curriculum of Chaos\"},{\"id\":\"strixhaven-owlin-flight-2\",\"name\":\"Flight\",\"description\":\"Thanks to your wings, you have a flying speed equal to your walking speed. You can't use this flying speed if you're wearing medium or heavy armor.\",\"level\":1,\"source\":\"Strixhaven: A Curriculum of Chaos\"},{\"id\":\"strixhaven-owlin-silent-feathers-3\",\"name\":\"Silent Feathers\",\"description\":\"You have proficiency in the Stealth skill.\",\"level\":1,\"source\":\"Strixhaven: A Curriculum of Chaos\"}],\"proficiencies\":[{\"name\":\"Stealth\",\"type\":\"skill\"}],\"languages\":[],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"}],\"classes\":[],\"subclasses\":[],\"backgrounds\":[{\"id\":\"strixhaven-lorehold-student\",\"name\":\"Lorehold Student\",\"description\":\"You have spent your youth preparing to be a student of Lorehold College, reading every book on the college's recommended reading list for prospective students. Your academic passions are in the broad field of history. You might dream of using magic to contact great historical figures or your own ancestors or of recreating the mighty magic of a distant age.\",\"skillProficiencies\":[\"History\",\"Religion\"],\"languageCount\":2,\"grantedFeatNames\":[\"Strixhaven Initiate\"],\"equipment\":[{\"name\":\"Ink (1-ounce bottle)\",\"type\":\"gear\"},{\"name\":\"Ink Pen\",\"type\":\"gear\"},{\"name\":\"Hammer\",\"type\":\"gear\"},{\"name\":\"Hooded Lantern\",\"type\":\"gear\"},{\"name\":\"Tinderbox\",\"type\":\"gear\"},{\"name\":\"tome of history\",\"type\":\"gear\"},{\"name\":\"school uniform\",\"type\":\"gear\"},{\"name\":\"Pouch\",\"type\":\"gear\"}],\"feature\":{\"name\":\"Feature: Lorehold Initiate\",\"description\":\"You gain the Strixhaven Initiate feat and must choose Lorehold within it. In addition, if you have the Spellcasting or Pact Magic feature, the spells on the Lorehold Spells table are added to the spell list of your spellcasting class. (If you are a multiclass character with multiple spell lists, these spells are added to all of them.) Lorehold Spells: 1st — Comprehend Languages, Identify; 2nd — Borrowed Knowledge, Locate Object; 3rd — Speak with Dead, Spirit Guardians; 4th — Arcane Eye, Stone Shape; 5th — Flame Strike, Legend Lore Consider customizing how your spells look when you cast them. Your Lorehold spells might create displays of golden light. You might use a tome or a scroll as a spellcasting focus, and your spell effects might reflect the appearance of the reference books you study.\"},\"personalityTraits\":[\"I thrive on esoteric lore. The more obscure the historical references I can include in everyday conversation, the better.\",\"By searching for these lost artifacts, I hope to find who I really am along the way.\",\"I can barely go a minute without talking about my research. I have so much knowledge in my head, and it needs to be let out somewhere!\",\"The spirits of the dead are so much more interesting to talk with than living classmates.\",\"I can speak eloquently about the historical ramifications of an ancient war. But ask me to add two-digit numbers together, and I'm a mess.\",\"In the end, it's all just entropy. Everything falls apart someday.\"],\"ideals\":[],\"bonds\":[],\"flaws\":[],\"suggestedCharacteristics\":[\"I thrive on esoteric lore. The more obscure the historical references I can include in everyday conversation, the better.\",\"By searching for these lost artifacts, I hope to find who I really am along the way.\",\"I can barely go a minute without talking about my research. I have so much knowledge in my head, and it needs to be let out somewhere!\",\"The spirits of the dead are so much more interesting to talk with than living classmates.\",\"I can speak eloquently about the historical ramifications of an ancient war. But ask me to add two-digit numbers together, and I'm a mess.\",\"In the end, it's all just entropy. Everything falls apart someday.\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-prismari-student\",\"name\":\"Prismari Student\",\"description\":\"You are an artist, and you have been preparing to hone your craft according to the traditions of Prismari College. Whatever your medium—sculpture, dance, paint, music, drama, architecture, or any other field—you have grand visions of bringing your art to life in a fusion of magic and creativity.\",\"skillProficiencies\":[\"Acrobatics\",\"Performance\"],\"toolProficiencies\":[\"One of your choice: AnyArtisansTool, Musical instrument\"],\"languageCount\":1,\"grantedFeatNames\":[\"Strixhaven Initiate\"],\"equipment\":[{\"name\":\"Ink (1-ounce bottle)\",\"type\":\"gear\"},{\"name\":\"Ink Pen\",\"type\":\"gear\"},{\"name\":\"Choose 1\",\"type\":\"tool\",\"alternatives\":[{\"name\":\"Any artisan's tools\",\"type\":\"tool\"},{\"name\":\"Any musical instrument\",\"type\":\"tool\"}]},{\"name\":\"school uniform\",\"type\":\"gear\"},{\"name\":\"Pouch\",\"type\":\"gear\"}],\"feature\":{\"name\":\"Feature: Prismari Initiate\",\"description\":\"You gain the Strixhaven Initiate feat and must choose Prismari within it. In addition, if you have the Spellcasting or Pact Magic feature, the spells on the Prismari Spells table are added to the spell list of your spellcasting class. (If you are a multiclass character with multiple spell lists, these spells are added to all of them.) Prismari Spells: 1st — Chromatic Orb, Thunderwave; 2nd — Flaming Sphere, Kinetic Jaunt; 3rd — Haste, Water Walk; 4th — Freedom of Movement, Wall of Fire; 5th — Cone of Cold, Conjure Elemental Consider customizing how your spells look when you cast them. You might wield your Prismari spells with dynamic, gestural movement—as much dance as somatic component. Even a blast of fire in your hands is a sculpted work of art; elemental forces make grand designs as you hurl spells. These forces might linger on your body or in your clothes as decorative elements after your spells are dissipated, as sparks dance in your hair and your touch leaves tracings of frost on whatever you touch.\"},\"personalityTraits\":[\"I'm the life of the party, and I expect everyone's attention when I walk into a room.\",\"Two weeks ago, I was enthralled with my latest project. Now, I think it's garbage and deserves to be destroyed.\",\"I believe everyone has the ability to express their truest selves through art, and I'm happy to quietly push them in the right direction.\",\"Everyone is a critic, and I work to win them all over.\",\"I'm beset with such an overwhelming sense of ennui regarding my art. Nothing quite captures my attention anymore.\",\"Instead of confronting my negative emotions, I channel them into explosive artistic displays.\"],\"ideals\":[],\"bonds\":[],\"flaws\":[],\"suggestedCharacteristics\":[\"I'm the life of the party, and I expect everyone's attention when I walk into a room.\",\"Two weeks ago, I was enthralled with my latest project. Now, I think it's garbage and deserves to be destroyed.\",\"I believe everyone has the ability to express their truest selves through art, and I'm happy to quietly push them in the right direction.\",\"Everyone is a critic, and I work to win them all over.\",\"I'm beset with such an overwhelming sense of ennui regarding my art. Nothing quite captures my attention anymore.\",\"Instead of confronting my negative emotions, I channel them into explosive artistic displays.\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-quandrix-student\",\"name\":\"Quandrix Student\",\"description\":\"In preparation to become a student of Quandrix College, you have spent years working through the college's math problems for prospective students. Your interests concentrate on the mathematical principles and patterns found in the natural world. You might lean more toward mathematics or physics, or you delve into more abstract studies of metaphysics, arcana, or logic.\",\"skillProficiencies\":[\"Arcana\",\"Nature\"],\"toolProficiencies\":[\"One type of artisan's tools\"],\"languageCount\":1,\"grantedFeatNames\":[\"Strixhaven Initiate\"],\"equipment\":[{\"name\":\"Ink (1-ounce bottle)\",\"type\":\"gear\"},{\"name\":\"Ink Pen\",\"type\":\"gear\"},{\"name\":\"Abacus\",\"type\":\"gear\"},{\"name\":\"book of arcane theory\",\"type\":\"gear\"},{\"name\":\"school uniform\",\"type\":\"gear\"},{\"name\":\"Pouch\",\"type\":\"gear\"}],\"feature\":{\"name\":\"Feature: Quandrix Initiate\",\"description\":\"You gain the Strixhaven Initiate feat and must choose Quandrix within it. In addition, if you have the Spellcasting or Pact Magic feature, the spells on the Quandrix Spells table are added to the spell list of your spellcasting class. (If you are a multiclass character with multiple spell lists, these spells are added to all of them.) Quandrix Spells: 1st — Entangle, Guiding Bolt; 2nd — Enlarge/Reduce, Vortex Warp; 3rd — Aura of Vitality, Haste; 4th — Control Water, Freedom of Movement; 5th — Circle of Power, Passwall Consider customizing how your spells look when you cast them. Your Quandrix spells might manifest amid kaleidoscopic swirls of fractal patterns, amplifying the tiniest movements of your somatic components. When your magic creates or alters creatures, it might briefly surround the targets with shimmering fractal designs or tessellated patterns.\"},\"personalityTraits\":[\"When I find a subject I'm interested in, I won't stop studying until I know everything about it. It keeps me up at night.\",\"I hope this all makes sense to me one day. Until then, I'm going to keep faking it.\",\"Equations and patterns come naturally to my mind. I wish friendship came just as easily.\",\"I believe I'm always the smartest person in the room. And I'll prove it, even if no one asks me to.\",\"If these classes have taught me anything, it's that reality is a lie, and nothing matters. So why bother?\",\"Before I graduate, I want to achieve something mathematically impossible. I must leave a legacy!\"],\"ideals\":[],\"bonds\":[],\"flaws\":[],\"suggestedCharacteristics\":[\"When I find a subject I'm interested in, I won't stop studying until I know everything about it. It keeps me up at night.\",\"I hope this all makes sense to me one day. Until then, I'm going to keep faking it.\",\"Equations and patterns come naturally to my mind. I wish friendship came just as easily.\",\"I believe I'm always the smartest person in the room. And I'll prove it, even if no one asks me to.\",\"If these classes have taught me anything, it's that reality is a lie, and nothing matters. So why bother?\",\"Before I graduate, I want to achieve something mathematically impossible. I must leave a legacy!\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-silverquill-student\",\"name\":\"Silverquill Student\",\"description\":\"You have spent years practicing your writing and oration in the hope of becoming a student of Silverquill College. Your studies focus on language, literature, and the power of words, both magical and otherwise. The metaphorical power of words to illuminate or conceal is joined with the literal ability of magic to do the same in your academic pursuits.\",\"skillProficiencies\":[\"Intimidation\",\"Persuasion\"],\"languageCount\":2,\"grantedFeatNames\":[\"Strixhaven Initiate\"],\"equipment\":[{\"name\":\"Ink (1-ounce bottle)\",\"type\":\"gear\"},{\"name\":\"Ink Pen\",\"type\":\"gear\"},{\"name\":\"book of poetry\",\"type\":\"gear\"},{\"name\":\"school uniform\",\"type\":\"gear\"},{\"name\":\"Pouch\",\"type\":\"gear\"}],\"feature\":{\"name\":\"Feature: Silverquill Initiate\",\"description\":\"You gain the Strixhaven Initiate feat and must choose Silverquill within it. In addition, if you have the Spellcasting or Pact Magic feature, the spells on the Silverquill Spells table are added to the spell list of your spellcasting class. (If you are a multiclass character with multiple spell lists, these spells are added to all of them.) Silverquill Spells: 1st — Dissonant Whispers, Silvery Barbs; 2nd — Calm Emotions, Darkness; 3rd — Beacon of Hope, Daylight; 4th — Compulsion, Confusion; 5th — Dominate Person, Rary's Telepathic Bond Consider customizing how your spells look when you cast them. Your Silverquill spells might be accompanied by visual effects resembling splotches of ink or radiating ripples of golden light. Any auditory effects of your spells often sound like amplified echoes of your own voice speaking the spells' verbal components—even amid the crash of lightning or a fiery eruption.\"},\"personalityTraits\":[\"I'll say whatever I need to in order to maintain my high social status.\",\"I prefer saying the blunt truth over a pretty lie, and I don't particularly care whose feelings I hurt.\",\"I believe that uplifting my peers is the best way to succeed.\",\"I've mastered the art of using humor as a defense, and I always have a charming joke ready.\",\"I always wait before speaking, analyzing the situation for whichever angle is most advantageous to my goals.\",\"No one knows about the all-nighters I've pulled to keep my magic looking effortless, and I'm going to keep it that way.\"],\"ideals\":[],\"bonds\":[],\"flaws\":[],\"suggestedCharacteristics\":[\"I'll say whatever I need to in order to maintain my high social status.\",\"I prefer saying the blunt truth over a pretty lie, and I don't particularly care whose feelings I hurt.\",\"I believe that uplifting my peers is the best way to succeed.\",\"I've mastered the art of using humor as a defense, and I always have a charming joke ready.\",\"I always wait before speaking, analyzing the situation for whichever angle is most advantageous to my goals.\",\"No one knows about the all-nighters I've pulled to keep my magic looking effortless, and I'm going to keep it that way.\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-witherbloom-student\",\"name\":\"Witherbloom Student\",\"description\":\"You filled your childhood with rudimentary alchemical experiments, all in the hope of becoming a student of Witherbloom College. The life sciences are the focus of your reading, which include biology and necromancy. Brewing strange concoctions with medicinal properties, exploring the anatomies of monsters, and cataloging swamp flora are the kinds of studies you might pursue at Witherbloom College.\",\"skillProficiencies\":[\"Nature\",\"Survival\"],\"toolProficiencies\":[\"Herbalism kit\"],\"languageCount\":1,\"grantedFeatNames\":[\"Strixhaven Initiate\"],\"equipment\":[{\"name\":\"Ink (1-ounce bottle)\",\"type\":\"gear\"},{\"name\":\"Ink Pen\",\"type\":\"gear\"},{\"name\":\"book about plant identification\",\"type\":\"gear\"},{\"name\":\"Iron Pot\",\"type\":\"gear\"},{\"name\":\"Herbalism Kit\",\"type\":\"tool\"},{\"name\":\"school uniform\",\"type\":\"gear\"},{\"name\":\"Pouch\",\"type\":\"gear\"}],\"feature\":{\"name\":\"Feature: Witherbloom Initiate\",\"description\":\"You gain the Strixhaven Initiate feat and must choose Witherbloom within it. In addition, if you have the Spellcasting or Pact Magic feature, the spells on the Witherbloom Spells table are added to the spell list of your spellcasting class. (If you are a multiclass character with multiple spell lists, these spells are added to all of them.) Witherbloom Spells: 1st — Cure Wounds, Inflict Wounds; 2nd — Lesser Restoration, Wither and Bloom; 3rd — Revivify, Vampiric Touch; 4th — Blight, Death Ward; 5th — Antilife Shell, Greater Restoration Consider customizing how your spells look when you cast them. Your Witherbloom spells might rely on material components or a spellcasting focus drawn from the swamp environment of Witherbloom, and your spells might take on an appearance suggesting those natural elements. Spectral shapes of swamp animals or plants might form amid your spell effects.\"},\"personalityTraits\":[\"I love brewing up a new recipe, even if some might be repulsed by my choice of ingredients. Or the final product. Or both.\",\"My fashion sense is like my garden: withered, black, and weird.\",\"I'm going to befriend every single monster in this swamp if it's the last thing I do.\",\"Everything in this world dies eventually. The question is, what will you do with the time you have left?\",\"I know we just met, but when you die, may I have your bones? For research.\",\"Don't interrupt me; I'm brooding.\"],\"ideals\":[],\"bonds\":[],\"flaws\":[],\"suggestedCharacteristics\":[\"I love brewing up a new recipe, even if some might be repulsed by my choice of ingredients. Or the final product. Or both.\",\"My fashion sense is like my garden: withered, black, and weird.\",\"I'm going to befriend every single monster in this swamp if it's the last thing I do.\",\"Everything in this world dies eventually. The question is, what will you do with the time you have left?\",\"I know we just met, but when you die, may I have your bones? For research.\",\"Don't interrupt me; I'm brooding.\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"}],\"spells\":[{\"id\":\"strixhaven-borrowed-knowledge\",\"name\":\"Borrowed Knowledge\",\"level\":2,\"school\":\"Divination\",\"castingTime\":\"1 action\",\"range\":\"self\",\"components\":[\"V\",\"S\",\"M (a book worth at least 25 gp)\"],\"duration\":\"1 hour\",\"description\":\"You draw on knowledge from spirits of the past. Choose one skill in which you lack proficiency. For the spell's duration, you have proficiency in the chosen skill. The spell ends early if you cast it again.\",\"ritual\":false,\"concentration\":false,\"classes\":[],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-kinetic-jaunt\",\"name\":\"Kinetic Jaunt\",\"level\":2,\"school\":\"Transmutation\",\"castingTime\":\"1 bonus\",\"range\":\"self\",\"components\":[\"S\"],\"duration\":\"Concentration, up to 1 minute\",\"description\":\"You magically empower your movement with dance-like steps, giving yourself the following benefits for the duration. Your walking speed increases by 10 feet. You don't provoke opportunity attacks. You can move through the space of another creature, and it doesn't count as 3. If you end your turn in another creature's space, you are shunted to the last unoccupied space you occupied, and you take 1d8 force damage.\",\"ritual\":false,\"concentration\":true,\"classes\":[],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-silvery-barbs\",\"name\":\"Silvery Barbs\",\"level\":1,\"school\":\"Enchantment\",\"castingTime\":\"1 reaction\",\"range\":\"60 feet\",\"components\":[\"V\"],\"duration\":\"instant\",\"description\":\"You magically distract the triggering creature and turn its momentary uncertainty into encouragement for another creature. The triggering creature must reroll the d20 and use the lower roll. You can then choose a different creature you can see within range (you can choose yourself). The chosen creature has advantage on the next attack roll, ability check, or saving throw it makes within 1 minute. A creature can be empowered by only one use of this spell at a time.\",\"ritual\":false,\"concentration\":false,\"classes\":[],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-vortex-warp\",\"name\":\"Vortex Warp\",\"level\":2,\"school\":\"Conjuration\",\"castingTime\":\"1 action\",\"range\":\"90 feet\",\"components\":[\"V\",\"S\"],\"duration\":\"instant\",\"description\":\"You magically twist space around another creature you can see within range. The target must succeed on a Constitution saving throw (the target can choose to fail), or the target is teleported to an unoccupied space of your choice that you can see within range. The chosen space must be on a surface or in a liquid that can support the target without the target having to squeeze.\",\"higherLevels\":\"At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the range of the spell increases by 30 feet for each slot level above 2nd.\",\"ritual\":false,\"concentration\":false,\"classes\":[],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-wither-and-bloom\",\"name\":\"Wither and Bloom\",\"level\":2,\"school\":\"Necromancy\",\"castingTime\":\"1 action\",\"range\":\"60 feet\",\"components\":[\"V\",\"S\",\"M (a withered vine twisted into a loop)\"],\"duration\":\"instant\",\"description\":\"You invoke both death and life upon a 10-foot-radius sphere centered on a point within range. Each creature of your choice in that area must make a Constitution saving throw, taking 2d6 necrotic damage on a failed save, or half as much damage on a successful one. Nonmagical vegetation in that area withers. In addition, one creature of your choice in that area can spend and roll one of its unspent Hit Dice and regain a number of hit points equal to the roll plus your spellcasting ability modifier.\",\"higherLevels\":\"At Higher Levels. When you cast this spell using a spell slot of 3rd level or higher, the damage increases by 2d6 for each slot above the 2nd, and the number of Hit Dice that can be spent and added to the healing roll increases by one for each slot above 2nd.\",\"ritual\":false,\"concentration\":false,\"classes\":[],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"}],\"equipment\":[{\"id\":\"strixhaven-alchemist-s-doom\",\"name\":\"Alchemist's Doom\",\"type\":\"gear\",\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":1,\"description\":\"This sticky, adhesive fluid ignites when exposed to air. As an action, you can throw this flask up to 20 feet, shattering it on impact. Make a ranged attack against a creature or object, treating the alchemist's doom as an improvised weapon. On a hit, the target takes 7 (2d6) fire damage at the start of each of its turns. A creature can end this damage by using its action to make a DC 10 Dexterity check to extinguish the flames.\",\"properties\":[]},{\"id\":\"strixhaven-bottle-of-boundless-coffee\",\"name\":\"Bottle of Boundless Coffee\",\"type\":\"gear\",\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"This metal bottle carries delicious, warm coffee. The bottle comes with a stopper, which is attached to the bottle by a little chain. Even when open, the bottle won't accept any liquid other than the coffee it produces. The coffee inside is always comfortably warm, and none of the heat can be felt through the bottle. Each time you drink the coffee, roll a d20. On a 1, the bottle refuses to dispense coffee for the next hour. If you pour coffee from the bottle, rather than drinking from it, the coffee vanishes the moment it leaves the bottle.\",\"properties\":[]},{\"id\":\"strixhaven-catapult-munition\",\"name\":\"Catapult Munition\",\"type\":\"gear\",\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"A catapult munition roughly the size and weight of a cannonball. The munition can be thrown up to 30 feet and explodes on impact. Any creature within a 15-foot-radius sphere centered on the point of impact must make a DC 14 Dexterity saving throw, taking 35 (10d6) fire damage on a failed save, or half as much damage on a successful one. In addition, each object in that area that isn't being worn or carried takes 35 (10d6) fire damage.\",\"properties\":[]},{\"id\":\"strixhaven-cuddly-strixhaven-mascot\",\"name\":\"Cuddly Strixhaven Mascot\",\"type\":\"gear\",\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"Representing one of the mascots of Strixhaven, this soft, Tiny, magic toy is perfect for cuddling. If you press it to your arm, shoulder, or leg as an action, the toy stays attached there for 1 hour or until you use an action to remove it. The toy can also be used to fight off fear. When you make a saving throw to avoid or end the frightened condition on yourself, you can give yourself advantage on the roll if the toy is on your person. You must decide to do so before rolling the d20. If the save succeeds, you can't use the toy in this way until you finish a long rest.\",\"properties\":[]},{\"id\":\"strixhaven-lorehold-primer\",\"name\":\"Lorehold Primer\",\"type\":\"gear\",\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"The Lorehold Primer is a magic textbook created at Strixhaven's Lorehold College. The primer has 3 charges, and it regains 1d3 expended charges daily at dawn. If you make an Intelligence (History) or Intelligence (Religion) check while holding the primer, you can expend 1 charge to give yourself 1d4 bonus to the check, immediately after you roll the d20. In addition, if you study the primer at the end of a long rest, you can choose one 1st-level spell from the cleric or wizard spell list. Before you finish your next long rest, you can cast the chosen spell once without a spell slot if you are holding the primer. Your spellcasting ability for this spell is your choice of Intelligence, Wisdom, or Charisma.\",\"properties\":[]},{\"id\":\"strixhaven-lorehold-trinket\",\"name\":\"Lorehold Trinket\",\"type\":\"gear\",\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"When you make your character, you may roll once on the Lorehold Trinkets table, instead of on the Trinkets table in the Player's Handbook, for your starting trinket. Lorehold Trinkets: 1 — A map made of concentric circles that can be rotated around the page; 2 — A puzzle box bedecked with amber; 3 — A dented brass compass with a red needle; 4 — The head of a broken statue that houses the consciousness of a snarky sage; 5 — A sheet of parchment embossed with tactile lettering, glowing red; 6 — A broken dagger with a wavy blade and a serpentine hilt\",\"properties\":[]},{\"id\":\"strixhaven-masque-charm\",\"name\":\"Masque Charm\",\"type\":\"gear\",\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"A masque charm is a small silver pin. While wearing this charm, you can use an action to cast the disguise self spell (DC 13 to discern the disguise). Once the spell is cast, it can't be cast from the charm again until the next sunset. When casting the spell, you can have the spell last for its normal 1 hour duration or for 6 hours. If you choose the 6-hour duration, the charm becomes nonmagical when the spell ends. In either case, the spell ends if the charm is removed from you.\",\"properties\":[]},{\"id\":\"strixhaven-murgaxor-s-elixir-of-life\",\"name\":\"Murgaxor's Elixir of Life\",\"type\":\"gear\",\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"Whoever drinks this concoction gains advantage on death saving throws for 24 hours.\",\"properties\":[]},{\"id\":\"strixhaven-murgaxor-s-orb\",\"name\":\"Murgaxor's Orb\",\"type\":\"gear\",\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"Roiling green mist fills this glass orb, which the exiled Strixhaven mage Murgaxor once used in foul magical experiments. Murgaxor's spirit has infused the orb, which he uses to spread a terrible curse among Strixhaven's students. Sentience. Murgaxor's orb is a sentient, chaotic evil magic item with the following properties: The orb has an Intelligence of 20, a Wisdom of 16, and a Charisma of 16, as well as hearing and darkvision out to a range of 30 feet. The orb can speak, read, and understand Common, and it can communicate telepathically with any creature touching it. At any time during your turn, the orb can cast the suggestion spell (save DC 17), targeting you or one other creature that touched the orb within the last 24 hours. This isn't a power of the orb that you control. Curse. Any Humanoid you touch while holding the orb must succeed on a DC 10 Wisdom saving throw or become cursed. Each creature cursed by the orb bears an echo of Murgaxor's hateful thoughts, and that creature suffers from headaches that are persistent but not debilitating until the curse ends. On your turn, the orb can use an action to produce one of the following effects, targeting one or more creatures it has cursed: Unconsciousness. The cursed creature falls unconscious for 1 hour. The creature is roused if it takes damage or someone uses an action to shake or slap it awake. Visions of Terror. The cursed creature sees terrifying visions, causing it to view all creatures that aren't also cursed as dangerous monsters for 10 minutes. The cursed creature must use its action each round to make one attack against the nearest non-cursed creature. If the cursed creature has multiple possible targets, it attacks one at random. This effect ends if the cursed creature is incapacitated. After either of these effects ends, the affected creature is no longer cursed. The curse can also be removed from a creature with a remove curse spell or similar magic. All cases of the curse end if Murgaxor's orb is destroyed. Magical Signature. As a side effect of the orb's curse, the spell detect magic reveals an aura of enchantment surrounding creatures bearing the curse. This aura is distinctive, but in a way detect magic offers no further details about. Destroying the Orb. Murgaxor's orb has AC 18; 20 hit points; immunity to necrotic, poison, and psychic damage; and resistance to all other types of damage. If reduced to 0 hit points, the orb shatters.\",\"properties\":[]},{\"id\":\"strixhaven-prismari-primer\",\"name\":\"Prismari Primer\",\"type\":\"gear\",\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"The Prismari Primer is a magic textbook created at Strixhaven's Prismari College. The primer has 3 charges, and it regains 1d3 expended charges daily at dawn. If you make a Dexterity (Acrobatics) or a Charisma (Performance) check while holding the primer, you can expend 1 charge to give yourself a 1d4 bonus to the check, immediately after you roll the d20. In addition, if you study the primer at the end of a long rest, you can choose one 1st-level spell from the bard or sorcerer spell list. Before you finish your next long rest, you can cast the chosen spell once without a spell slot if you are holding the primer. Your spellcasting ability for this spell is your choice of Intelligence, Wisdom, or Charisma.\",\"properties\":[]},{\"id\":\"strixhaven-prismari-trinket\",\"name\":\"Prismari Trinket\",\"type\":\"gear\",\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"When you make your character, you may roll once on the Prismari Trinkets table, instead of on the Trinkets table in the Player's Handbook, for your starting trinket. Prismari Trinkets: 1 — A pair of rose-tinted glasses with glittery frames; 2 — A stoppered glass bottle that, when opened, plays a brassy orchestral piece; 3 — A quartet of hovering water motes in a vial; 4 — A bandolier of watercolor paints; 5 — A tiara capped with a crystal that crackles with harmless lightning; 6 — An iridescent quill\",\"properties\":[]},{\"id\":\"strixhaven-quandrix-primer\",\"name\":\"Quandrix Primer\",\"type\":\"gear\",\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"The Quandrix Primer is a magic textbook created at Strixhaven's Quandrix College. The primer has 3 charges, and it regains 1d3 expended charges daily at dawn. If you make an Intelligence (Arcana) or an Intelligence (Nature) check while holding the primer, you can expend 1 charge to give yourself a 1d4 bonus to the check, immediately after you roll the d20. In addition, if you study the primer at the end of a long rest, you can choose one 1st-level spell from the druid or wizard spell list. Before you finish your next long rest, you can cast the chosen spell once without a spell slot if you are holding the primer. Your spellcasting ability for this spell is your choice of Intelligence, Wisdom, or Charisma.\",\"properties\":[]},{\"id\":\"strixhaven-quandrix-trinket\",\"name\":\"Quandrix Trinket\",\"type\":\"gear\",\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"When you make your character, you may roll once on the Quandrix Trinkets table, instead of on the Trinkets table in the Player's Handbook, for your starting trinket. Quandrix Trinkets: 1 — A small succulent in a dodecahedral clay pot; 2 — A blue knit hat that looks a bit like a bottle folding in on itself; 3 — A model hypercube carved from green crystal, showcasing the fourth dimension; 4 — A crumpled test on the theory of gravity manipulation, with a failing grade on the front and the name of a famous Quandrix professor; 5 — A blue tetrahedron that, when tapped twice, projects a recording of an old mathematics lecture; 6 — A round bread roll cut so that someone could spread butter on both halves without ever lifting the knife\",\"properties\":[]},{\"id\":\"strixhaven-silverquill-primer\",\"name\":\"Silverquill Primer\",\"type\":\"gear\",\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"The Silverquill Primer is a magic textbook created at Strixhaven's Silverquill College. The primer has 3 charges, and it regains 1d3 expended charges daily at dawn. If you make a Charisma (Intimidation) or a Charisma (Persuasion) check while holding the primer, you can expend 1 charge to give yourself a 1d4 bonus to the check, immediately after you roll the d20. In addition, if you study the primer at the end of a long rest, you can choose one 1st-level spell from the bard or cleric spell list. Before you finish your next long rest, you can cast the chosen spell once without a spell slot if you are holding the primer. Your spellcasting ability for this spell is your choice of Intelligence, Wisdom, or Charisma.\",\"properties\":[]},{\"id\":\"strixhaven-silverquill-trinket\",\"name\":\"Silverquill Trinket\",\"type\":\"gear\",\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"When you make your character, you may roll once on the Silverquill Trinkets table, instead of on the Trinkets table in the Player's Handbook, for your starting trinket. Silverquill Trinkets: 1 — A black leather notebook filled with half-finished poems; 2 — A set of flashcards detailing different colloquialisms and their meanings; 3 — A canteen that makes any liquid drunk from it taste sweet; 4 — A forged permission slip granting access to the special archives of Strixhaven's libraries; 5 — A stylish silver pin that references a famous series of novels about warlocks; 6 — A stack of small pieces of parchment, each enchanted to stick to whatever surface it's pressed against and peel off easily\",\"properties\":[]},{\"id\":\"strixhaven-strixhaven-pennant\",\"name\":\"Strixhaven Pennant\",\"type\":\"gear\",\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"This magic pennant bears the symbol of Strixhaven or one of its colleges: Lorehold, Prismari, Quandrix, Silverquill, or Witherbloom. While you wave the pennant, the symbol on it glitters, and the pennant sheds bright light in a 10-foot-radius and dim light for an additional 10 feet.\",\"properties\":[]},{\"id\":\"strixhaven-witherbloom-primer\",\"name\":\"Witherbloom Primer\",\"type\":\"gear\",\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"The Witherbloom Primer is a magic textbook created at Strixhaven's Witherbloom College. The primer has 3 charges, and it regains 1d3 expended charges daily at dawn. If you make an Intelligence (Nature) or Wisdom (Survival) check while holding the primer, you can expend 1 charge to give yourself a 1d4 bonus to the check, immediately after you roll the d20. In addition, if you study the primer at the end of a long rest, you can choose one 1st-level spell from the druid or wizard spell list. Before you finish your next long rest, you can cast the chosen spell once without a spell slot if you are holding the primer. Your spellcasting ability for this spell is your choice of Intelligence, Wisdom, or Charisma.\",\"properties\":[]},{\"id\":\"strixhaven-witherbloom-trinket\",\"name\":\"Witherbloom Trinket\",\"type\":\"gear\",\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\",\"cost\":{\"amount\":0,\"unit\":\"gp\"},\"weight\":0,\"description\":\"When you make your character, you may roll once on the Witherbloom Trinkets table, instead of on the Trinkets table in the Player's Handbook, for your starting trinket. Witherbloom Trinkets: 1 — A black bird-shaped mask, trimmed with glowing green thread; 2 — A set of rabbit bones; 3 — A pair of thick knee-high waders, stained with muck and moss; 4 — A slimy green tentacle, which occasionally wriggles; 5 — A notebook containing waterproof paper; 6 — A necklace of five small vials, each filled with luminescent white liquid\",\"properties\":[]}],\"feats\":[{\"id\":\"strixhaven-strixhaven-initiate\",\"name\":\"Strixhaven Initiate\",\"description\":\"You have studied some magical theory and have learned a few spells associated with Strixhaven University. Choose one of Strixhaven's colleges: Lorehold, Prismari, Quandrix, Silverquill, or Witherbloom. You learn two cantrips and one 1st-level spell based on the college you choose, as specified in the Strixhaven Spells table. You can cast the chosen 1st-level spell without a spell slot, and you must finish a long rest before you can cast it in this way again. You can also cast the spell using any spell slots you have. Your spellcasting ability for this feat's spells is Intelligence, Wisdom, or Charisma (choose when you select this feat). Strixhaven Spells: Lorehold — Choose two from light, sacred flame, and thaumaturgy. — Choose one 1st-level level=1.; Prismari — Choose two from fire bolt, prestidigitation, and ray of frost. — Choose one 1st-level level=1.; Quandrix — Choose two from druidcraft, guidance, and mage hand. — Choose one 1st-level level=1.; Silverquill — Choose two from sacred flame, thaumaturgy, and vicious mockery. — Choose one 1st-level level=1.; Witherbloom — Choose two from chill touch, druidcraft, and spare the dying. — Choose one 1st-level level=1.\",\"grantedSpells\":[\"Light\",\"Sacred Flame\",\"Thaumaturgy\",\"Fire Bolt\",\"Prestidigitation\",\"Ray Of Frost\",\"Druidcraft\",\"Guidance\",\"Mage Hand\",\"Vicious Mockery\",\"Chill Touch\",\"Spare The Dying\"],\"spellChoices\":[{\"id\":\"strixhaven-strixhaven-initiate-spell-choice-0\",\"count\":1,\"level\":1,\"classes\":[\"Cleric\",\"Wizard\"],\"label\":\"Choose one 1st-level spell from the Cleric or Wizard spell list\"},{\"id\":\"strixhaven-strixhaven-initiate-spell-choice-1\",\"count\":1,\"level\":1,\"classes\":[\"Cleric\",\"Wizard\"],\"label\":\"Choose one 1st-level spell from the Cleric or Wizard spell list\"},{\"id\":\"strixhaven-strixhaven-initiate-spell-choice-2\",\"count\":1,\"level\":1,\"classes\":[\"Cleric\",\"Wizard\"],\"label\":\"Choose one 1st-level spell from the Cleric or Wizard spell list\"},{\"id\":\"strixhaven-strixhaven-initiate-spell-choice-3\",\"count\":1,\"level\":1,\"classes\":[\"Bard\",\"Sorcerer\"],\"label\":\"Choose one 1st-level spell from the Bard or Sorcerer spell list\"},{\"id\":\"strixhaven-strixhaven-initiate-spell-choice-4\",\"count\":1,\"level\":1,\"classes\":[\"Bard\",\"Sorcerer\"],\"label\":\"Choose one 1st-level spell from the Bard or Sorcerer spell list\"},{\"id\":\"strixhaven-strixhaven-initiate-spell-choice-5\",\"count\":1,\"level\":1,\"classes\":[\"Bard\",\"Sorcerer\"],\"label\":\"Choose one 1st-level spell from the Bard or Sorcerer spell list\"},{\"id\":\"strixhaven-strixhaven-initiate-spell-choice-6\",\"count\":1,\"level\":1,\"classes\":[\"Druid\",\"Wizard\"],\"label\":\"Choose one 1st-level spell from the Druid or Wizard spell list\"},{\"id\":\"strixhaven-strixhaven-initiate-spell-choice-7\",\"count\":1,\"level\":1,\"classes\":[\"Druid\",\"Wizard\"],\"label\":\"Choose one 1st-level spell from the Druid or Wizard spell list\"},{\"id\":\"strixhaven-strixhaven-initiate-spell-choice-8\",\"count\":1,\"level\":1,\"classes\":[\"Druid\",\"Wizard\"],\"label\":\"Choose one 1st-level spell from the Druid or Wizard spell list\"},{\"id\":\"strixhaven-strixhaven-initiate-spell-choice-9\",\"count\":1,\"level\":1,\"classes\":[\"Bard\",\"Cleric\"],\"label\":\"Choose one 1st-level spell from the Bard or Cleric spell list\"},{\"id\":\"strixhaven-strixhaven-initiate-spell-choice-10\",\"count\":1,\"level\":1,\"classes\":[\"Bard\",\"Cleric\"],\"label\":\"Choose one 1st-level spell from the Bard or Cleric spell list\"},{\"id\":\"strixhaven-strixhaven-initiate-spell-choice-11\",\"count\":1,\"level\":1,\"classes\":[\"Bard\",\"Cleric\"],\"label\":\"Choose one 1st-level spell from the Bard or Cleric spell list\"},{\"id\":\"strixhaven-strixhaven-initiate-spell-choice-12\",\"count\":1,\"level\":1,\"classes\":[\"Druid\",\"Wizard\"],\"label\":\"Choose one 1st-level spell from the Druid or Wizard spell list\"},{\"id\":\"strixhaven-strixhaven-initiate-spell-choice-13\",\"count\":1,\"level\":1,\"classes\":[\"Druid\",\"Wizard\"],\"label\":\"Choose one 1st-level spell from the Druid or Wizard spell list\"},{\"id\":\"strixhaven-strixhaven-initiate-spell-choice-14\",\"count\":1,\"level\":1,\"classes\":[\"Druid\",\"Wizard\"],\"label\":\"Choose one 1st-level spell from the Druid or Wizard spell list\"}],\"features\":[],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-strixhaven-mascot\",\"name\":\"Strixhaven Mascot\",\"description\":\"You have learned how to summon a Strixhaven mascot to assist you, granting you these benefits: You can cast the find familiar spell as a ritual. Your familiar can take the form of the mascot associated with the college you chose for the Strixhaven Initiate feat: a spirit statue mascot (Lorehold), an art elemental mascot (Prismari), a fractal mascot (Quandrix), an inkling mascot (Silverquill), or a pest mascot (Witherbloom). When you take the Attack action on your turn, you can forgo one attack to allow your mascot familiar to make one attack of its own with its reaction. If your mascot familiar is within 60 feet of you, you can teleport as an action, swapping places with the familiar. If your destination space is too small for you to occupy, the teleportation fails and is wasted. Once you teleport in this way, you can't do so again until you finish a long rest, unless you expend a spell slot of 2nd level or higher to do it again.\",\"prerequisites\":{\"level\":4,\"text\":\"Level 4\"},\"grantedSpells\":[\"Find Familiar\"],\"features\":[],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"}],\"monsters\":[{\"id\":\"strixhaven-archaic\",\"name\":\"Archaic\",\"description\":\"Archaic from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Gargantuan\",\"type\":\"celestial\",\"alignment\":\"N\",\"ac\":20,\"hp\":{\"average\":245,\"formula\":\"14d20 + 98\"},\"speed\":\"40 ft.\",\"abilityScores\":{\"strength\":25,\"dexterity\":10,\"constitution\":24,\"intelligence\":27,\"wisdom\":24,\"charisma\":20},\"challengeRating\":\"18\",\"savingThrows\":[\"Dex +6\",\"Int +14\",\"Wis +13\",\"Cha +11\"],\"skills\":[\"Arcana +20\",\"Deception +11\",\"History +20\",\"Perception +13\"],\"damageResistances\":[\"force\"],\"damageImmunities\":[\"poison\",\"psychic\"],\"conditionImmunities\":[\"charmed\",\"exhaustion\",\"frightened\",\"paralyzed\",\"petrified\",\"poisoned\",\"stunned\"],\"senses\":[\"truesight 120 ft., passive Perception 23\"],\"traits\":[{\"id\":\"strixhaven-archaic-trait-0\",\"name\":\"Enigmatic Mind\",\"description\":\"The archaic's mind can't be read, creatures can communicate telepathically with the archaic only if it allows, and magic can't determine whether the archaic is lying.\"},{\"id\":\"strixhaven-archaic-trait-1\",\"name\":\"Legendary Resistance (3/Day)\",\"description\":\"If the archaic fails a saving throw, it can choose to succeed instead.\"},{\"id\":\"strixhaven-archaic-trait-2\",\"name\":\"Unusual Nature\",\"description\":\"The archaic doesn't require air, food, drink, or sleep.\"}],\"actions\":[{\"id\":\"strixhaven-archaic-action-0\",\"name\":\"Multiattack\",\"description\":\"The archaic makes two Force Strike attacks. It can also use Gravity Shift, if available.\"},{\"id\":\"strixhaven-archaic-action-1\",\"name\":\"Force Strike\",\"description\":\"Melee or Ranged Spell Attack: +14 to hit, reach 15 ft. or range 120 ft., one target. Hit: 19 (2d10 + 8) force damage, and the target is pulled up to 10 feet toward the archaic or pushed 10 feet away from it, as the archaic chooses.\"},{\"id\":\"strixhaven-archaic-action-2\",\"name\":\"Gravity Shift (Recharge 5-6)\",\"description\":\"The archaic reverses gravity for one creature it can see within 100 feet of itself. The creature must succeed on a DC 22 Wisdom saving throw or fall 100 feet upward. If the falling creature encounters a solid object (such as a ceiling) in this fall, it strikes the object just as it would during a downward fall. If the creature reaches the top of the area without striking anything, it hovers there until the start of the archaic's next turn, at which time gravity returns to normal and the creature falls.\"},{\"id\":\"strixhaven-archaic-action-3\",\"name\":\"Teleport\",\"description\":\"The archaic teleports to an unoccupied space that it can see within 120 feet of itself.\"},{\"id\":\"strixhaven-archaic-spellcasting-0\",\"name\":\"Spellcasting\",\"description\":\"The archaic casts one of the following spells, requiring no material components and using Intelligence as the spellcasting ability (spell save DC 22):\\n\\n- At will: detect magic, divination, sending\\n- 1/day each: banishment, forcecage\"}],\"bonusActions\":[],\"reactions\":[{\"id\":\"strixhaven-archaic-reaction-0\",\"name\":\"Spell Mimicry (1/Day)\",\"description\":\"Immediately after a creature the archaic can see casts a spell of 5th level or lower, that creature must succeed on a DC 22 Charisma saving throw, or the archaic immediately casts the same spell at the same level (+14 to hit with spell attacks, spell save DC 22), requiring no material components and choosing the spell's targets.\"}],\"legendaryActions\":[{\"id\":\"strixhaven-archaic-legendary-0\",\"name\":\"Strike\",\"description\":\"The archaic makes one Force Strike attack.\"},{\"id\":\"strixhaven-archaic-legendary-1\",\"name\":\"Teleport\",\"description\":\"The archaic uses Teleport.\"},{\"id\":\"strixhaven-archaic-legendary-2\",\"name\":\"Unravel Magic (Costs 2 Actions)\",\"description\":\"The archaic targets one creature it can see within 120 feet of itself. The target must succeed on a DC 22 Constitution saving throw or take 35 (10d6) force damage, and each spell of 5th level or lower on the target ends.\"}],\"languages\":[\"all\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-art-elemental-mascot\",\"name\":\"Art Elemental Mascot\",\"description\":\"Art Elemental Mascot from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Small\",\"type\":\"elemental\",\"alignment\":\"N\",\"ac\":11,\"hp\":{\"average\":18,\"formula\":\"4d6 + 4\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":6,\"dexterity\":13,\"constitution\":12,\"intelligence\":8,\"wisdom\":11,\"charisma\":15},\"challengeRating\":\"1/4\",\"skills\":[\"Performance +4\"],\"damageResistances\":[\"cold\",\"fire\"],\"damageImmunities\":[\"poison\"],\"conditionImmunities\":[\"poisoned\"],\"senses\":[\"passive Perception 10\"],\"traits\":[{\"id\":\"strixhaven-art-elemental-mascot-trait-0\",\"name\":\"Death Burst\",\"description\":\"When the elemental dies, it explodes in a burst of colored light. Each creature within 5 feet of the elemental must succeed on a DC 11 Constitution saving throw or be blinded for 1 minute. A blinded creature can repeat the save at the end of each of its turns, ending the effect on itself on a success.\"}],\"actions\":[{\"id\":\"strixhaven-art-elemental-mascot-action-0\",\"name\":\"Joyful Flare\",\"description\":\"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 6 (2d4 + 1) fire damage.\"},{\"id\":\"strixhaven-art-elemental-mascot-action-1\",\"name\":\"Melancholic Bolt\",\"description\":\"Ranged Weapon Attack: +3 to hit, range 30 ft., one target. Hit: 6 (2d4 + 1) cold damage.\"},{\"id\":\"strixhaven-art-elemental-mascot-action-2\",\"name\":\"Captivating Artistry (1/Day)\",\"description\":\"The elemental targets one creature it can see within 30 feet of itself. The target must succeed on a DC 12 Charisma saving throw or be charmed for 1 minute. The charmed target can repeat the save at the end of each of its turns, ending the effect on itself on a success.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"understands the languages of its creator but can't speak\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-beledros-witherbloom\",\"name\":\"Beledros Witherbloom\",\"description\":\"Beledros Witherbloom from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Gargantuan\",\"type\":\"dragon\",\"alignment\":\"N G\",\"ac\":22,\"hp\":{\"average\":444,\"formula\":\"24d20 + 192\"},\"speed\":\"40 ft., fly 80 ft., swim 40 ft.\",\"abilityScores\":{\"strength\":28,\"dexterity\":14,\"constitution\":27,\"intelligence\":18,\"wisdom\":28,\"charisma\":17},\"challengeRating\":\"24\",\"savingThrows\":[\"Dex +9\",\"Con +15\",\"Wis +16\",\"Cha +10\"],\"skills\":[\"Arcana +18\",\"Medicine +16\",\"Nature +18\",\"Perception +16\"],\"damageImmunities\":[\"necrotic\",\"poison\"],\"conditionImmunities\":[\"poisoned\"],\"senses\":[\"blindsight 120 ft., passive Perception 26\"],\"traits\":[{\"id\":\"strixhaven-beledros-witherbloom-trait-0\",\"name\":\"Legendary Resistance (3/Day)\",\"description\":\"If Beledros fails a saving throw, she can choose to succeed instead.\"},{\"id\":\"strixhaven-beledros-witherbloom-trait-1\",\"name\":\"Unusual Nature\",\"description\":\"Beledros doesn't require air, food, or drink.\"}],\"actions\":[{\"id\":\"strixhaven-beledros-witherbloom-action-0\",\"name\":\"Multiattack\",\"description\":\"Beledros makes one Bite attack and two Claw attacks.\"},{\"id\":\"strixhaven-beledros-witherbloom-action-1\",\"name\":\"Bite\",\"description\":\"Melee Weapon Attack: +16 to hit, reach 15 ft., one target. Hit: 14 (1d10 + 9) piercing damage plus 6 (1d12) necrotic damage.\"},{\"id\":\"strixhaven-beledros-witherbloom-action-2\",\"name\":\"Claw\",\"description\":\"Melee Weapon Attack: +16 to hit, reach 10 ft., one target. Hit: 12 (1d6 + 9) slashing damage. If the target is a Huge or smaller creature, it is knocked prone.\"},{\"id\":\"strixhaven-beledros-witherbloom-action-3\",\"name\":\"Decaying Breath (Recharge 5-6)\",\"description\":\"Beledros exhales decaying energy in a 90-foot cone. Each creature in that area must make a DC 23 Constitution saving throw, taking 39 (6d12) necrotic damage and 39 (6d12) poison damage on a failed save, or half as much damage on a successful one. A creature that takes damage from the breath can't regain hit points until the start of Beledros's next turn.\"},{\"id\":\"strixhaven-beledros-witherbloom-action-4\",\"name\":\"Miasmal Flow\",\"description\":\"Beledros becomes a swirling cloud of green mist and can move up to half her flying speed without provoking opportunity attacks, then resumes her true form. During this movement, she can move through creatures and objects as if they were 3. If she moves through a creature, it must succeed on a DC 23 Constitution saving throw or become poisoned until the end of its next turn. If Beledros ends this move inside an object, she takes 5 (1d10) force damage and is shunted to the nearest unoccupied space.\"},{\"id\":\"strixhaven-beledros-witherbloom-spellcasting-0\",\"name\":\"Spellcasting\",\"description\":\"Beledros casts one of the following spells, requiring no material components and using Wisdom as the spellcasting ability:\\n\\n- 1/day each: greater restoration, mass cure wounds, plant growth, revivify, speak with dead\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[{\"id\":\"strixhaven-beledros-witherbloom-legendary-0\",\"name\":\"Claw\",\"description\":\"Beledros makes one Claw attack.\"},{\"id\":\"strixhaven-beledros-witherbloom-legendary-1\",\"name\":\"Miasmal Flow (Costs 2 Actions)\",\"description\":\"Beledros uses Miasmal Flow.\"},{\"id\":\"strixhaven-beledros-witherbloom-legendary-2\",\"name\":\"Teeming with Life (Costs 3 Actions)\",\"description\":\"Beledros magically summons 1d4 pest mascots in unoccupied spaces she can see within 60 feet of herself. The pests obey her commands and take their turns immediately after hers. Any creature, other than a pest, takes 9 (2d8) poison damage if it starts its turn within 5 feet of one or more of these pests. When one of these pests drops to 0 hit points, Beledros regains 9 hit points. These pests disappear after 10 minutes, when Beledros dies, or when she uses this action again.\"}],\"languages\":[\"Common\",\"Draconic\",\"Druidic\",\"Sylvan\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-brackish-trudge\",\"name\":\"Brackish Trudge\",\"description\":\"Brackish Trudge from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Large\",\"type\":\"plant\",\"alignment\":\"U\",\"ac\":12,\"hp\":{\"average\":68,\"formula\":\"8d10 + 24\"},\"speed\":\"30 ft., swim 30 ft.\",\"abilityScores\":{\"strength\":20,\"dexterity\":10,\"constitution\":17,\"intelligence\":4,\"wisdom\":14,\"charisma\":4},\"challengeRating\":\"3\",\"skills\":[\"Perception +4\"],\"damageResistances\":[\"fire\"],\"senses\":[\"blindsight 10 ft., passive Perception 14\"],\"traits\":[{\"id\":\"strixhaven-brackish-trudge-trait-0\",\"name\":\"Fungal Fortitude\",\"description\":\"If damage reduces the trudge to 0 hit points, it must make a Constitution saving throw with a DC of 5 + the damage taken, unless the damage is radiant or from a critical hit. On a success, the trudge drops to 1 hit point instead.\"}],\"actions\":[{\"id\":\"strixhaven-brackish-trudge-action-0\",\"name\":\"Tusk\",\"description\":\"Melee Weapon Attack: +7 to hit, reach 10 ft., one target. Hit: 16 (2d10 + 5) piercing damage plus 3 (1d6) poison damage. If the target is a creature, it must succeed on a DC 15 Strength saving throw or be knocked prone.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-cogwork-archivist\",\"name\":\"Cogwork Archivist\",\"description\":\"Cogwork Archivist from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Large\",\"type\":\"construct\",\"alignment\":\"L N\",\"ac\":17,\"hp\":{\"average\":90,\"formula\":\"12d10 + 24\"},\"speed\":\"40 ft.\",\"abilityScores\":{\"strength\":18,\"dexterity\":10,\"constitution\":15,\"intelligence\":17,\"wisdom\":11,\"charisma\":6},\"challengeRating\":\"4\",\"skills\":[\"Arcana +5\",\"History +5\",\"Nature +5\",\"Perception +2\",\"Religion +5\"],\"damageImmunities\":[\"poison\"],\"conditionImmunities\":[\"charmed\",\"exhaustion\",\"frightened\",\"petrified\",\"poisoned\"],\"senses\":[\"darkvision 60 ft., passive Perception 12\"],\"traits\":[{\"id\":\"strixhaven-cogwork-archivist-trait-0\",\"name\":\"Magic Resistance\",\"description\":\"The archivist has advantage on saving throws against spells and other magical effects.\"}],\"actions\":[{\"id\":\"strixhaven-cogwork-archivist-action-0\",\"name\":\"Multiattack\",\"description\":\"The archivist makes two Grasping Limb attacks.\"},{\"id\":\"strixhaven-cogwork-archivist-action-1\",\"name\":\"Grasping Limb\",\"description\":\"Melee Weapon Attack: +6 to hit, reach 15 ft., one target. Hit: 13 (2d8 + 4) bludgeoning damage, and the target is grappled (escape DC 14). The archivist can have no more than two targets grappled at a time.\"},{\"id\":\"strixhaven-cogwork-archivist-spellcasting-0\",\"name\":\"Spellcasting\",\"description\":\"The archivist casts one of the following spells, requiring no material components and using Intelligence as the spellcasting ability:\\n\\n- At will: dancing lights, prestidigitation\\n- 2/day: silence\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"all\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-daemogoth\",\"name\":\"Daemogoth\",\"description\":\"Daemogoth from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Huge\",\"type\":\"fiend\",\"alignment\":\"L E\",\"ac\":16,\"hp\":{\"average\":157,\"formula\":\"15d12 + 60\"},\"speed\":\"40 ft., climb 40 ft.\",\"abilityScores\":{\"strength\":19,\"dexterity\":15,\"constitution\":19,\"intelligence\":21,\"wisdom\":14,\"charisma\":18},\"challengeRating\":\"10\",\"savingThrows\":[\"Int +9\",\"Wis +6\",\"Cha +8\"],\"skills\":[\"Arcana +13\",\"Deception +12\",\"History +9\",\"Perception +6\"],\"damageImmunities\":[\"psychic\"],\"conditionImmunities\":[\"frightened\"],\"senses\":[\"truesight 120 ft., passive Perception 16\"],\"traits\":[{\"id\":\"strixhaven-daemogoth-trait-0\",\"name\":\"Pact of Pain\",\"description\":\"Using a 10-minute ritual, the daemogoth can forge a magical bond with a willing creature it touches throughout the ritual. The creature becomes bound by the pact until it dies, the daemogoth dies, or the pact is broken by any effect that can remove a curse. The daemogoth chooses one spell from the level=0;1;2;3. The bound creature can cast that spell using this pact, requiring no material components and using Intelligence as the spellcasting ability. When it casts the spell, the creature takes 7 (2d6) psychic damage, which can't break the creature's concentration on a spell. Once the bound creature casts the spell in this way, it can't do so again until it finishes a long rest.\"}],\"actions\":[{\"id\":\"strixhaven-daemogoth-action-0\",\"name\":\"Multiattack\",\"description\":\"The daemogoth makes three Agonizing Burst attacks. It can use Terrify, if available, in place of one of the attacks.\"},{\"id\":\"strixhaven-daemogoth-action-1\",\"name\":\"Agonizing Burst\",\"description\":\"Melee or Ranged Spell Attack: +9 to hit, reach 10 ft. or range 120 ft., one target. Hit: 11 (2d10) force damage. If the target is a creature, the daemogoth regains 5 hit points.\"},{\"id\":\"strixhaven-daemogoth-action-2\",\"name\":\"Terrify (Recharge 4-6)\",\"description\":\"The daemogoth targets one creature it can see within 120 feet of itself. The target must make a DC 17 Wisdom saving throw. On a failed save, the target takes 33 (6d10) psychic damage and is frightened of the daemogoth until the end of the daemogoth's next turn, and the daemogoth regains 5 hit points. On a successful save, the target takes half as much damage and isn't frightened, and the daemogoth doesn't heal.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Abyssal\",\"Infernal\",\"telepathy 120 ft.\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-daemogoth-titan\",\"name\":\"Daemogoth Titan\",\"description\":\"Daemogoth Titan from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Gargantuan\",\"type\":\"fiend\",\"alignment\":\"C E\",\"ac\":17,\"hp\":{\"average\":203,\"formula\":\"11d20 + 88\"},\"speed\":\"40 ft.\",\"abilityScores\":{\"strength\":26,\"dexterity\":10,\"constitution\":26,\"intelligence\":24,\"wisdom\":18,\"charisma\":20},\"challengeRating\":\"16\",\"savingThrows\":[\"Int +12\",\"Wis +9\",\"Cha +10\"],\"skills\":[\"Arcana +17\",\"Deception +15\",\"History +12\",\"Perception +9\"],\"damageImmunities\":[\"psychic\"],\"conditionImmunities\":[\"charmed\",\"frightened\"],\"senses\":[\"truesight 120 ft., passive Perception 19\"],\"traits\":[{\"id\":\"strixhaven-daemogoth-titan-trait-0\",\"name\":\"Legendary Resistance (3/Day)\",\"description\":\"If the titan fails a saving throw, it can choose to succeed instead.\"},{\"id\":\"strixhaven-daemogoth-titan-trait-1\",\"name\":\"Pact of Suffering\",\"description\":\"Using a 10-minute long ritual, the titan can forge a magical bond with a willing creature it touches throughout the ritual. The creature becomes bound by the pact until it dies, the titan dies, or the pact is broken by a wish spell. The titan chooses one spell from the level=0;1;2;3;4;5;6;7;8. The bound creature can cast that spell using this pact, requiring no material components and using Intelligence as the spellcasting ability. When it casts the spell, the creature takes 21 (6d6) psychic damage, which can't break the creature's concentration on a spell. Once the bound creature casts the spell in this way, it can't do so again until it finishes a long rest.\"}],\"actions\":[{\"id\":\"strixhaven-daemogoth-titan-action-0\",\"name\":\"Multiattack\",\"description\":\"The titan makes two Agonizing Burst attacks.\"},{\"id\":\"strixhaven-daemogoth-titan-action-1\",\"name\":\"Agonizing Burst\",\"description\":\"Melee or Ranged Spell Attack: +12 to hit, reach 15 ft. or range 120 ft., one target. Hit: 17 (3d6 + 7) force damage. If the target is a creature, the titan regains 5 hit points.\"},{\"id\":\"strixhaven-daemogoth-titan-action-2\",\"name\":\"Teleport\",\"description\":\"The titan teleports to an unoccupied space it can see within 120 feet of itself.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[{\"id\":\"strixhaven-daemogoth-titan-legendary-0\",\"name\":\"Attack\",\"description\":\"The titan makes one Agonizing Burst attack.\"},{\"id\":\"strixhaven-daemogoth-titan-legendary-1\",\"name\":\"Stalking Nightmare (Costs 2 Actions)\",\"description\":\"The titan uses Teleport, after which it can target one creature within 20 feet of itself that it can see. The target must make a DC 20 Constitution saving throw. On a failed save, the target takes 22 (4d10) necrotic damage, and the titan regains 10 hit points. On a successful save, the target takes half as much damage, and the titan doesn't heal.\"},{\"id\":\"strixhaven-daemogoth-titan-legendary-2\",\"name\":\"Terrorize (Costs 3 Actions)\",\"description\":\"The titan targets one creature it can see within 120 feet of itself. The target must make a DC 20 Wisdom saving throw. On a failed save, the target takes 38 (7d10) psychic damage and is frightened of the titan until the end of the target's next turn, and the titan regains 15 hit points. On a successful save, the target takes half as much damage and isn't frightened, and the titan doesn't heal.\"}],\"languages\":[\"Abyssal\",\"Infernal\",\"telepathy 120 ft.\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-first-year-student\",\"name\":\"First-Year Student\",\"description\":\"First-Year Student from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Small\",\"type\":\"humanoid\",\"alignment\":\"A\",\"ac\":11,\"hp\":{\"average\":33,\"formula\":\"6d8 + 6\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":8,\"dexterity\":12,\"constitution\":13,\"intelligence\":12,\"wisdom\":10,\"charisma\":11},\"challengeRating\":\"1/2\",\"senses\":[\"passive Perception 10\"],\"traits\":[{\"id\":\"strixhaven-first-year-student-trait-0\",\"name\":\"Excited to Be Here\",\"description\":\"The student has advantage on initiative rolls.\"}],\"actions\":[{\"id\":\"strixhaven-first-year-student-action-0\",\"name\":\"Magic Flare\",\"description\":\"Melee or Ranged Spell Attack: +3 to hit, reach 5 ft. or range 60 ft., one target. Hit: 7 (1d12 + 1) force damage.\"},{\"id\":\"strixhaven-first-year-student-spellcasting-0\",\"name\":\"Spellcasting\",\"description\":\"The student casts one of the following spells, using Intelligence as the spellcasting ability (spell save DC 11):\\n\\n- At will: mage hand, prestidigitation\\n- 1/day: detect magic\"}],\"bonusActions\":[],\"reactions\":[{\"id\":\"strixhaven-first-year-student-reaction-0\",\"name\":\"Beginner's Luck (2/Day)\",\"description\":\"When the student fails a saving throw, it can reroll the d20. It must use the new roll.\"}],\"legendaryActions\":[],\"languages\":[\"Common plus any two languages\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-fractal-mascot\",\"name\":\"Fractal Mascot\",\"description\":\"Fractal Mascot from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Small\",\"type\":\"construct\",\"alignment\":\"N\",\"ac\":12,\"hp\":{\"average\":27,\"formula\":\"6d6 + 6\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":12,\"dexterity\":14,\"constitution\":13,\"intelligence\":7,\"wisdom\":10,\"charisma\":5},\"challengeRating\":\"1/4\",\"damageImmunities\":[\"poison\"],\"conditionImmunities\":[\"poisoned\"],\"senses\":[\"passive Perception 10\"],\"traits\":[{\"id\":\"strixhaven-fractal-mascot-trait-0\",\"name\":\"Relative Density\",\"description\":\"The fractal can move through creatures and objects as if they were 3. It takes 5 (1d10) force damage if it ends its turn inside an object.\"}],\"actions\":[{\"id\":\"strixhaven-fractal-mascot-action-0\",\"name\":\"Quantum Strike\",\"description\":\"Melee Weapon Attack: +3 to hit, reach 5 ft., one target. Hit: 3 (1d4 + 1) force damage, or 6 (2d4 + 1) force damage if the fractal is Medium or bigger.\"}],\"bonusActions\":[{\"id\":\"strixhaven-fractal-mascot-bonus-0\",\"name\":\"Augment\",\"description\":\"The fractal's size increases by one category. While the fractal is Medium or bigger, it makes Strength checks and Strength saving throws with advantage. The fractal can become no larger than Huge via this bonus action.\"},{\"id\":\"strixhaven-fractal-mascot-bonus-1\",\"name\":\"Diminish\",\"description\":\"The fractal's size decreases by one category. While the fractal is Tiny, it makes attack rolls, Dexterity checks, and Dexterity saving throws with advantage. The fractal can become no smaller than 1 foot in height via this bonus action.\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"understands the languages of its creator but can't speak\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-galazeth-prismari\",\"name\":\"Galazeth Prismari\",\"description\":\"Galazeth Prismari from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Gargantuan\",\"type\":\"dragon\",\"alignment\":\"C N\",\"ac\":21,\"hp\":{\"average\":402,\"formula\":\"23d20 + 161\"},\"speed\":\"40 ft., fly 80 ft.\",\"abilityScores\":{\"strength\":26,\"dexterity\":14,\"constitution\":25,\"intelligence\":18,\"wisdom\":20,\"charisma\":26},\"challengeRating\":\"23\",\"savingThrows\":[\"Dex +9\",\"Con +14\",\"Wis +12\",\"Cha +15\"],\"skills\":[\"Acrobatics +16\",\"Arcana +18\",\"Perception +12\",\"Performance +22\"],\"damageResistances\":[\"lightning\"],\"damageImmunities\":[\"cold\",\"fire\"],\"senses\":[\"blindsight 120 ft., passive Perception 22\"],\"traits\":[{\"id\":\"strixhaven-galazeth-prismari-trait-0\",\"name\":\"Legendary Resistance (3/Day)\",\"description\":\"If Galazeth fails a saving throw, he can choose to succeed instead.\"}],\"actions\":[{\"id\":\"strixhaven-galazeth-prismari-action-0\",\"name\":\"Multiattack\",\"description\":\"Galazeth makes one Bite attack and two Claw attacks.\"},{\"id\":\"strixhaven-galazeth-prismari-action-1\",\"name\":\"Bite\",\"description\":\"Melee Weapon Attack: +15 to hit, reach 15 ft., one target. Hit: 13 (1d10 + 8) piercing damage plus 5 (1d10) lightning damage.\"},{\"id\":\"strixhaven-galazeth-prismari-action-2\",\"name\":\"Claw\",\"description\":\"Melee Weapon Attack: +15 to hit, reach 10 ft., one target. Hit: 11 (1d6 + 8) slashing damage. If the target is a Large or smaller creature, it is knocked prone.\"},{\"id\":\"strixhaven-galazeth-prismari-action-3\",\"name\":\"Dancing Elements Breath (Recharge 5-6)\",\"description\":\"Galazeth exhales a blast of flames and ice in a 90-foot cone. Each creature in that area must make a DC 22 Dexterity saving throw, gaining no benefit from cover (other than 3) and taking 38 (7d10) fire damage and 38 (7d10) cold damage on a failed save, or half as much damage on a successful one.\"},{\"id\":\"strixhaven-galazeth-prismari-spellcasting-0\",\"name\":\"Spellcasting\",\"description\":\"Galazeth casts one of the following spells, requiring no material components and using Charisma as the spellcasting ability (spell save DC 23):\\n\\n- 1/day each: control water, gust of wind, wall of stone\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[{\"id\":\"strixhaven-galazeth-prismari-legendary-0\",\"name\":\"Claw\",\"description\":\"Galazeth makes one Claw attack.\"},{\"id\":\"strixhaven-galazeth-prismari-legendary-1\",\"name\":\"Lightning Flash (Costs 2 Actions)\",\"description\":\"Galazeth moves up to half his flying speed without provoking opportunity attacks. When he passes within 15 feet of a creature during this move, that creature must succeed on a DC 22 Dexterity saving throw or take 11 (2d10) lightning damage. A creature can take this damage no more than once during the move.\"},{\"id\":\"strixhaven-galazeth-prismari-legendary-2\",\"name\":\"Flowing Creation (Costs 3 Actions)\",\"description\":\"Galazeth magically summons 1d4 elemental mascots in unoccupied spaces he can see within 60 feet of himself. The art elementals obey his commands and take their turns immediately after his. Any creature, other than an art elemental, takes 5 (1d10) cold, fire, or lightning damage (Galazeth's choice) if it ends its turn within 5 feet of one or more of these elementals. When one of these elementals drops to 0 hit points, Galazeth can fly up to 20 feet without provoking opportunity attacks. These elementals disappear after 10 minutes, when Galazeth dies, or when he uses this action again.\"}],\"languages\":[\"Common\",\"Draconic\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-groff\",\"name\":\"Groff\",\"description\":\"Groff from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Large\",\"type\":\"plant\",\"alignment\":\"U\",\"ac\":13,\"hp\":{\"average\":68,\"formula\":\"8d10 + 24\"},\"speed\":\"30 ft., swim 30 ft.\",\"abilityScores\":{\"strength\":20,\"dexterity\":10,\"constitution\":17,\"intelligence\":4,\"wisdom\":13,\"charisma\":7},\"challengeRating\":\"4\",\"skills\":[\"Perception +3\",\"Stealth +4\"],\"senses\":[\"darkvision 60 ft., passive Perception 13\"],\"traits\":[{\"id\":\"strixhaven-groff-trait-0\",\"name\":\"False Appearance\",\"description\":\"If the groff is motionless at the start of combat, it has advantage on its initiative roll. Moreover, if a creature hasn't observed the groff move or act, that creature must succeed on a DC 18 Intelligence (Investigation) check to discern that the groff isn't an ordinary moss-covered bog patch.\"},{\"id\":\"strixhaven-groff-trait-1\",\"name\":\"Hold Breath\",\"description\":\"The groff can hold its breath for up to 1 hour.\"}],\"actions\":[{\"id\":\"strixhaven-groff-action-0\",\"name\":\"Multiattack\",\"description\":\"The groff makes one Bite attack and one Swamp Claw attack.\"},{\"id\":\"strixhaven-groff-action-1\",\"name\":\"Bite\",\"description\":\"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 9 (1d8 + 5) piercing damage.\"},{\"id\":\"strixhaven-groff-action-2\",\"name\":\"Swamp Claw\",\"description\":\"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 8 (1d6 + 5) slashing damage. If the target is a Medium or smaller creature, it must succeed on a DC 15 Strength saving throw or become engulfed by the groff. While engulfed, the target can't breathe, is restrained, and takes 10 (3d6) poison damage at the start of each of its turns. When the groff moves, the engulfed target moves with it. The groff can have only one target engulfed at a time. An engulfed target can repeat the saving throw at the end of its turns. On a success, the target escapes and enters the nearest unoccupied space.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-inkling-mascot\",\"name\":\"Inkling Mascot\",\"description\":\"Inkling Mascot from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Tiny\",\"type\":\"ooze\",\"alignment\":\"N\",\"ac\":13,\"hp\":{\"average\":18,\"formula\":\"4d4 + 8\"},\"speed\":\"10 ft., fly 30 ft.\",\"abilityScores\":{\"strength\":10,\"dexterity\":16,\"constitution\":14,\"intelligence\":6,\"wisdom\":7,\"charisma\":11},\"challengeRating\":\"1/4\",\"skills\":[\"Stealth +5\"],\"damageImmunities\":[\"psychic\"],\"conditionImmunities\":[\"blinded\",\"charmed\",\"deafened\",\"exhaustion\",\"prone\"],\"senses\":[\"blindsight 60 ft., passive Perception 8\"],\"traits\":[{\"id\":\"strixhaven-inkling-mascot-trait-0\",\"name\":\"Amorphous\",\"description\":\"The inkling can move through a space as narrow as 1 inch wide without squeezing.\"}],\"actions\":[{\"id\":\"strixhaven-inkling-mascot-action-0\",\"name\":\"Blot\",\"description\":\"Melee Weapon Attack: +5 to hit, reach 5 ft., one target. Hit: 5 (1d4 + 3) psychic damage.\"},{\"id\":\"strixhaven-inkling-mascot-action-1\",\"name\":\"Ink Spray (1/Day)\",\"description\":\"The inkling sprays viscous ink at one creature within 15 feet of itself. The target must succeed on a DC 12 Constitution saving throw or be blinded until the end of the inkling's next turn.\"}],\"bonusActions\":[{\"id\":\"strixhaven-inkling-mascot-bonus-0\",\"name\":\"Shadow Stealth\",\"description\":\"While in dim light or darkness, the inkling takes the Hide action.\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"understands the languages of its creator but can't speak\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-lorehold-apprentice\",\"name\":\"Lorehold Apprentice\",\"description\":\"Lorehold Apprentice from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Small\",\"type\":\"humanoid\",\"alignment\":\"A\",\"ac\":12,\"hp\":{\"average\":33,\"formula\":\"6d8 + 6\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":10,\"dexterity\":14,\"constitution\":13,\"intelligence\":15,\"wisdom\":12,\"charisma\":11},\"challengeRating\":\"2\",\"savingThrows\":[\"Con +3\",\"Int +4\"],\"skills\":[\"History +6\",\"Insight +3\",\"Investigation +6\"],\"senses\":[\"passive Perception 11\"],\"traits\":[],\"actions\":[{\"id\":\"strixhaven-lorehold-apprentice-action-0\",\"name\":\"Scroll Bash\",\"description\":\"Melee Spell Attack: +4 to hit, reach 30 ft., one target. Hit: 7 (1d10 + 2) bludgeoning damage plus 9 (2d8) thunder damage.\"},{\"id\":\"strixhaven-lorehold-apprentice-action-1\",\"name\":\"Reduce to Memory (Recharge 6)\",\"description\":\"Thundering golden energy erupts around a creature the apprentice can see within 90 feet of it. The creature must make a DC 12 Constitution saving throw, taking 33 (6d10) thunder damage on a failed save, or half as much damage on a successful one. A Construct has disadvantage on the saving throw.\"},{\"id\":\"strixhaven-lorehold-apprentice-spellcasting-0\",\"name\":\"Spellcasting\",\"description\":\"The apprentice casts one of the following spells, requiring no material components and using Intelligence as the spellcasting ability (spell save DC 12):\\n\\n- At will: guidance, light\\n- 1/day each: comprehend languages, locate object, mage armor\"}],\"bonusActions\":[],\"reactions\":[{\"id\":\"strixhaven-lorehold-apprentice-reaction-0\",\"name\":\"Learn from the Past (2/Day)\",\"description\":\"When another creature within 60 feet of the apprentice misses a target with an attack roll, the apprentice magically enables the attacker to reroll the attack roll. It must use the new roll.\"}],\"legendaryActions\":[],\"languages\":[\"Common plus any two languages\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-lorehold-pledgemage\",\"name\":\"Lorehold Pledgemage\",\"description\":\"Lorehold Pledgemage from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Small\",\"type\":\"humanoid\",\"alignment\":\"A\",\"ac\":13,\"hp\":{\"average\":60,\"formula\":\"11d8 + 11\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":10,\"dexterity\":16,\"constitution\":13,\"intelligence\":17,\"wisdom\":12,\"charisma\":11},\"challengeRating\":\"4\",\"savingThrows\":[\"Con +3\",\"Int +5\"],\"skills\":[\"History +7\",\"Insight +3\",\"Investigation +7\"],\"senses\":[\"passive Perception 11\"],\"traits\":[],\"actions\":[{\"id\":\"strixhaven-lorehold-pledgemage-action-0\",\"name\":\"Multiattack\",\"description\":\"The pledgemage makes two Scroll Bash attacks.\"},{\"id\":\"strixhaven-lorehold-pledgemage-action-1\",\"name\":\"Scroll Bash\",\"description\":\"Melee Spell Attack: +5 to hit, reach 30 ft., one target. Hit: 8 (1d10 + 3) bludgeoning damage plus 9 (2d8) thunder damage.\"},{\"id\":\"strixhaven-lorehold-pledgemage-action-2\",\"name\":\"Reduce to Memory (Recharge 5-6)\",\"description\":\"Thundering golden energy erupts around a creature the pledgemage can see within 90 feet of it. The creature must make a DC 13 Constitution saving throw, taking 44 (8d10) thunder damage on a failed save, or half as much damage on a successful one. A Construct has disadvantage on the saving throw.\"},{\"id\":\"strixhaven-lorehold-pledgemage-spellcasting-0\",\"name\":\"Spellcasting\",\"description\":\"The pledgemage casts one of the following spells, requiring no material components and using Intelligence as the spellcasting ability (spell save DC 13):\\n\\n- At will: guidance, light\\n- 2/day each: comprehend languages, locate object\\n- 1/day each: mage armor, speak with dead, stone shape\"}],\"bonusActions\":[{\"id\":\"strixhaven-lorehold-pledgemage-bonus-0\",\"name\":\"Chronal Break (1/Day)\",\"description\":\"The pledgemage chooses a point within 30 feet of itself, shunting the minds of nearby creatures out of this moment in time. Each creature in a 10-foot-radius sphere centered on that point must succeed on a DC 13 Wisdom saving throw or be incapacitated until the end of the pledgemage's next turn.\"}],\"reactions\":[{\"id\":\"strixhaven-lorehold-pledgemage-reaction-0\",\"name\":\"Learn from the Past (2/Day)\",\"description\":\"When another creature within 60 feet of the pledgemage misses a target with an attack roll, the pledgemage magically enables the attacker to reroll the attack roll. It must use the new roll.\"}],\"legendaryActions\":[],\"languages\":[\"Common plus any two languages\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-lorehold-professor-of-chaos\",\"name\":\"Lorehold Professor of Chaos\",\"description\":\"Lorehold Professor of Chaos from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Small\",\"type\":\"humanoid\",\"alignment\":\"A\",\"ac\":12,\"hp\":{\"average\":110,\"formula\":\"17d8 + 34\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":11,\"dexterity\":14,\"constitution\":14,\"intelligence\":19,\"wisdom\":15,\"charisma\":13},\"challengeRating\":\"7\",\"savingThrows\":[\"Con +5\",\"Int +7\",\"Wis +5\",\"Cha +4\"],\"skills\":[\"Arcana +7\",\"History +7\",\"Perception +5\"],\"senses\":[\"passive Perception 15\"],\"traits\":[{\"id\":\"strixhaven-lorehold-professor-of-chaos-trait-0\",\"name\":\"Voice from the Past (1/Day)\",\"description\":\"The professor can cast the contact other plane spell to contact a long-dead spirit, using Intelligence as the spellcasting ability.\"}],\"actions\":[{\"id\":\"strixhaven-lorehold-professor-of-chaos-action-0\",\"name\":\"Multiattack\",\"description\":\"The professor makes two Spectral Scroll attacks. It can also use Weight of History, if available.\"},{\"id\":\"strixhaven-lorehold-professor-of-chaos-action-1\",\"name\":\"Spectral Scroll\",\"description\":\"Melee Spell Attack: +7 to hit, reach 30 ft., one target. Hit: 15 (2d10 + 4) force damage. If the target is a creature, it must succeed on a DC 15 Strength saving throw or be knocked prone.\"},{\"id\":\"strixhaven-lorehold-professor-of-chaos-action-2\",\"name\":\"Weight of History (Recharge 5-6)\",\"description\":\"The professor magically compresses time around up to six creatures of its choice that it can see within 30 feet of itself. Each target must succeed on a DC 15 Wisdom saving throw or be restrained for 1 minute, but the restrained target's speed is halved instead of being reduced to 0. At the start of each of its turns, the restrained target takes 4 (1d8) force damage. A restrained target can repeat the save at the end of each of its turns, ending the effect on itself on a success.\"},{\"id\":\"strixhaven-lorehold-professor-of-chaos-spellcasting-0\",\"name\":\"Spellcasting\",\"description\":\"The professor casts one of the following spells, requiring no material components and using Intelligence as the spellcasting ability:\\n\\n- At will: comprehend languages, dancing lights, guidance\\n- 2/day each: locate object, mage armor, passwall\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common plus any four languages\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-lorehold-professor-of-order\",\"name\":\"Lorehold Professor of Order\",\"description\":\"Lorehold Professor of Order from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Small\",\"type\":\"humanoid\",\"alignment\":\"A\",\"ac\":12,\"hp\":{\"average\":104,\"formula\":\"16d8 + 32\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":11,\"dexterity\":14,\"constitution\":14,\"intelligence\":19,\"wisdom\":15,\"charisma\":13},\"challengeRating\":\"7\",\"savingThrows\":[\"Con +5\",\"Int +7\",\"Wis +5\",\"Cha +4\"],\"skills\":[\"Arcana +7\",\"History +7\",\"Perception +5\"],\"damageResistances\":[\"force\"],\"senses\":[\"passive Perception 15\"],\"traits\":[{\"id\":\"strixhaven-lorehold-professor-of-order-trait-0\",\"name\":\"Voice from the Past (1/Day)\",\"description\":\"The professor can cast the contact other plane spell to contact a long-dead spirit, using Intelligence as the spellcasting ability.\"}],\"actions\":[{\"id\":\"strixhaven-lorehold-professor-of-order-action-0\",\"name\":\"Multiattack\",\"description\":\"The professor makes two Repelling Burst attacks. It can also use Force Barrier, if available.\"},{\"id\":\"strixhaven-lorehold-professor-of-order-action-1\",\"name\":\"Repelling Burst\",\"description\":\"Melee Spell Attack: +7 to hit, reach 30 ft., one target. Hit: 13 (2d8 + 4) force damage. If the target is a Large or smaller creature, it must succeed on a DC 15 Strength saving throw or be pushed up to 10 feet directly away from the professor and become restrained until the start of professor's next turn.\"},{\"id\":\"strixhaven-lorehold-professor-of-order-action-2\",\"name\":\"Force Barrier (Recharge 5-6)\",\"description\":\"The professor magically creates a wall of translucent, golden force within 90 feet of itself. The wall lasts for 1 minute or until the professor uses this action again. The barrier can be a vertical or horizontal plane up to 30 feet on a side or a 10-foot-radius hemispherical dome with a floor. The wall provides 3. It has AC 17, 30 hit points, and immunity to poison and psychic damage.\"},{\"id\":\"strixhaven-lorehold-professor-of-order-spellcasting-0\",\"name\":\"Spellcasting\",\"description\":\"The professor casts one of the following spells, requiring no material components and using Intelligence as the spellcasting ability (spell save DC 15):\\n\\n- At will: comprehend languages, guidance, light\\n- 2/day each: dimension door, locate object, mage armor, stone shape\"}],\"bonusActions\":[],\"reactions\":[{\"id\":\"strixhaven-lorehold-professor-of-order-reaction-0\",\"name\":\"Arcane Stasis (2/Day)\",\"description\":\"When a creature the professor can see within 60 feet of it casts a spell, the professor can magically lock the casting in the moment before completion. The spellcaster must succeed on a DC 15 saving throw using the spell's spellcasting ability, or the spell fails and is wasted.\"}],\"legendaryActions\":[],\"languages\":[\"Common plus any four languages\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-mage-hunter\",\"name\":\"Mage Hunter\",\"description\":\"Mage Hunter from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Large\",\"type\":\"monstrosity\",\"alignment\":\"L E\",\"ac\":15,\"hp\":{\"average\":85,\"formula\":\"10d10 + 30\"},\"speed\":\"40 ft., climb 40 ft., fly 10 ft.\",\"abilityScores\":{\"strength\":19,\"dexterity\":15,\"constitution\":16,\"intelligence\":11,\"wisdom\":17,\"charisma\":10},\"challengeRating\":\"5\",\"savingThrows\":[\"Int +3\",\"Wis +6\",\"Cha +3\"],\"skills\":[\"Perception +9\",\"Stealth +5\"],\"conditionImmunities\":[\"blinded\",\"charmed\",\"deafened\",\"frightened\",\"prone\"],\"senses\":[\"blindsight 120 ft. (blind beyond this radius), passive Perception 19\"],\"traits\":[{\"id\":\"strixhaven-mage-hunter-trait-0\",\"name\":\"Magic Sense\",\"description\":\"The hunter knows the location of every spellcaster, active spell, and magic item within 120 feet of itself.\"},{\"id\":\"strixhaven-mage-hunter-trait-1\",\"name\":\"Spider Climb (Hunter Form Only)\",\"description\":\"The hunter can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check.\"}],\"actions\":[{\"id\":\"strixhaven-mage-hunter-action-0\",\"name\":\"Multiattack (Hunter Form Only)\",\"description\":\"The hunter makes two Claw attacks.\"},{\"id\":\"strixhaven-mage-hunter-action-1\",\"name\":\"Claw (Hunter Form Only)\",\"description\":\"Melee Weapon Attack: +7 to hit, reach 5 ft., one target. Hit: 15 (2d10 + 4) slashing damage.\"},{\"id\":\"strixhaven-mage-hunter-action-2\",\"name\":\"Tail\",\"description\":\"Melee Weapon Attack: +7 to hit, reach 10 ft., one target. Hit: 22 (4d8 + 4) piercing damage, and the target is grappled (escape DC 15). Until this grapple ends, the target is restrained, and the hunter can't make a Tail attack against another target.\"},{\"id\":\"strixhaven-mage-hunter-action-3\",\"name\":\"Mage Tracker (Sentry Form Only)\",\"description\":\"The hunter emits a pulse of energy that helps it better locate its magical quarry. Each creature within 120 feet of the hunter that has the ability to cast spells must succeed on a DC 14 Wisdom saving throw or be mystically marked by the hunter for 1 hour. While marked, a creature can't become hidden from the hunter and gains no benefit from the invisible condition against the hunter. Additionally, while a marked creature is on the same plane of existence as the hunter, the hunter always knows the distance and direction to the creature.\"}],\"bonusActions\":[{\"id\":\"strixhaven-mage-hunter-bonus-0\",\"name\":\"Shift Form\",\"description\":\"The hunter folds into its drone-like sentry form or unfolds into its hunter form. Its game statistics are the same in each form.\"}],\"reactions\":[{\"id\":\"strixhaven-mage-hunter-reaction-0\",\"name\":\"Consume and Destroy\",\"description\":\"When the hunter takes damage from a spell, it takes only half the triggering damage (rounded down). If the creature that cast the spell is within 60 feet of the hunter, that creature must succeed on a DC 14 Dexterity saving throw or take the other half of the damage.\"}],\"legendaryActions\":[],\"languages\":[\"understands Common but can't speak\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-murgaxor\",\"name\":\"Murgaxor\",\"description\":\"Murgaxor from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Medium\",\"type\":\"humanoid\",\"alignment\":\"N E\",\"ac\":16,\"hp\":{\"average\":127,\"formula\":\"15d8 + 60\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":11,\"dexterity\":14,\"constitution\":18,\"intelligence\":20,\"wisdom\":12,\"charisma\":12},\"challengeRating\":\"9\",\"savingThrows\":[\"Con +8\",\"Int +9\",\"Wis +5\",\"Cha +5\"],\"skills\":[\"Deception +9\",\"Medicine +5\",\"Survival +5\"],\"damageResistances\":[\"necrotic\"],\"conditionImmunities\":[\"exhaustion\"],\"senses\":[\"passive Perception 11\"],\"traits\":[{\"id\":\"strixhaven-murgaxor-trait-0\",\"name\":\"Blood Aegis\",\"description\":\"The AC of Murgaxor includes his Constitution modifier while he isn't wearing armor or wielding a shield.\"},{\"id\":\"strixhaven-murgaxor-trait-1\",\"name\":\"Oriq Mask\",\"description\":\"Murgaxor wears an Oriq mask. While wearing the mask, Murgaxor can't be targeted by any divination magic or perceived through magical scrying sensors, and he adds double his proficiency bonus to Charisma (Deception) checks (included above).\"},{\"id\":\"strixhaven-murgaxor-trait-2\",\"name\":\"Sanguine Sense\",\"description\":\"While Murgaxor isn't blinded, he can see any creature that isn't an Undead or a Construct within 60 feet of himself, even through 3, 2 areas, invisibility, or any other phenomena that would prevent sight.\"}],\"actions\":[{\"id\":\"strixhaven-murgaxor-action-0\",\"name\":\"Multiattack\",\"description\":\"Murgaxor makes two Blood Lash attacks.\"},{\"id\":\"strixhaven-murgaxor-action-1\",\"name\":\"Blood Lash\",\"description\":\"Melee Spell Attack: +9 to hit, reach 10 ft., one target. Hit: 21 (3d10 + 5) necrotic damage. If the target is a creature, it can't regain hit points until the start of Murgaxor's next turn.\"},{\"id\":\"strixhaven-murgaxor-action-2\",\"name\":\"Blood Boil (Recharge 4-6)\",\"description\":\"Murgaxor chooses a point within 150 feet of himself, and a 20-foot radius sphere centered on that point fills with a burst of searing, blood-red mist. Each creature of Murgaxor's choice that he can see in that area must make a DC 17 Constitution saving throw. On a failed save, a creature takes 38 (7d10) necrotic damage and is incapacitated until the end of its next turn. On a success, a creature takes half as much damage and isn't incapacitated. A creature dies if reduced to 0 hit points by this necrotic damage.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common plus any four languages\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-oracle-of-strixhaven\",\"name\":\"Oracle of Strixhaven\",\"description\":\"Oracle of Strixhaven from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Medium\",\"type\":\"humanoid\",\"alignment\":\"N G\",\"ac\":12,\"hp\":{\"average\":150,\"formula\":\"20d8 + 60\"},\"speed\":\"30 ft., fly 15 ft.\",\"abilityScores\":{\"strength\":12,\"dexterity\":15,\"constitution\":16,\"intelligence\":21,\"wisdom\":20,\"charisma\":18},\"challengeRating\":\"15\",\"savingThrows\":[\"Con +8\",\"Int +10\",\"Wis +10\",\"Cha +9\"],\"skills\":[\"Arcana +15\",\"Insight +15\",\"Investigation +15\",\"Nature +10\",\"Perception +10\"],\"conditionImmunities\":[\"charmed\",\"frightened\"],\"senses\":[\"passive Perception 20\"],\"traits\":[{\"id\":\"strixhaven-oracle-of-strixhaven-trait-0\",\"name\":\"Legendary Resistance (3/Day)\",\"description\":\"If the Oracle fails a saving throw, she can choose to succeed instead.\"}],\"actions\":[{\"id\":\"strixhaven-oracle-of-strixhaven-action-0\",\"name\":\"Multiattack\",\"description\":\"The Oracle makes two Magic Flare attacks. She can also use Paradoxy, if available.\"},{\"id\":\"strixhaven-oracle-of-strixhaven-action-1\",\"name\":\"Magic Flare\",\"description\":\"Melee or Ranged Spell Attack: +10 to hit, reach 5 ft. or range 60 ft., one target. Hit: 24 (3d12 + 5) force damage.\"},{\"id\":\"strixhaven-oracle-of-strixhaven-action-2\",\"name\":\"Paradoxy (Recharge 4-6)\",\"description\":\"Momentary warps in reality appear at three different points the Oracle can see within 120 feet of her. Each creature in a 20-foot-radius sphere centered on each point must make a DC 18 Strength saving throw. On a failed save, a creature takes 33 (6d10) force damage and is pulled up to 15 feet in a straight line toward the center of the sphere. On a successful save, the creature takes half as much damage and isn't pulled. A creature caught in the area of multiple warps is affected by only one, which the Oracle chooses.\"},{\"id\":\"strixhaven-oracle-of-strixhaven-action-3\",\"name\":\"Teleport\",\"description\":\"The Oracle teleports, along with any equipment she is wearing or carrying, to an unoccupied space she can see within 60 feet of herself.\"},{\"id\":\"strixhaven-oracle-of-strixhaven-spellcasting-0\",\"name\":\"Spellcasting\",\"description\":\"The Oracle casts one of the following spells, requiring no material components and using Intelligence as the spellcasting ability (spell save DC 18):\\n\\n- At will: detect magic\\n- 2/day each: dispel magic, mage armor, remove curse, sending\\n- 1/day each: power word stun, scrying (as an action), wall of force\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[{\"id\":\"strixhaven-oracle-of-strixhaven-legendary-0\",\"name\":\"Vector Shift\",\"description\":\"The Oracle teleports one creature she can see within 60 feet of herself, along with any equipment it is wearing or carrying, to an unoccupied space within 30 feet of herself. An unwilling target must succeed on a DC 18 Charisma saving throw to avoid the effect.\"},{\"id\":\"strixhaven-oracle-of-strixhaven-legendary-1\",\"name\":\"Spellcasting (Costs 2 Actions)\",\"description\":\"The Oracle uses Spellcasting.\"},{\"id\":\"strixhaven-oracle-of-strixhaven-legendary-2\",\"name\":\"Vortex Jaunt (Costs 2 Actions)\",\"description\":\"The Oracle uses Teleport, and immediately after she disappears, each creature within 30 feet of the space she left must succeed on a DC 18 Constitution saving throw or take 16 (3d10) force damage.\"}],\"languages\":[\"all\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-oriq-blood-mage\",\"name\":\"Oriq Blood Mage\",\"description\":\"Oriq Blood Mage from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Medium\",\"type\":\"humanoid\",\"alignment\":\"N E\",\"ac\":16,\"hp\":{\"average\":127,\"formula\":\"15d8 + 60\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":11,\"dexterity\":14,\"constitution\":18,\"intelligence\":20,\"wisdom\":12,\"charisma\":12},\"challengeRating\":\"9\",\"savingThrows\":[\"Con +8\",\"Int +9\",\"Wis +5\",\"Cha +5\"],\"skills\":[\"Deception +9\",\"Medicine +5\",\"Survival +5\"],\"damageResistances\":[\"necrotic\"],\"conditionImmunities\":[\"exhaustion\"],\"senses\":[\"passive Perception 11\"],\"traits\":[{\"id\":\"strixhaven-oriq-blood-mage-trait-0\",\"name\":\"Blood Aegis\",\"description\":\"The AC of the blood mage includes its Constitution modifier while it isn't wearing armor or wielding a shield.\"},{\"id\":\"strixhaven-oriq-blood-mage-trait-1\",\"name\":\"Oriq Mask\",\"description\":\"The blood mage wears an Oriq mask. While wearing the mask, the blood mage can't be targeted by any divination magic or perceived through magical scrying sensors, and it adds double its proficiency bonus to Charisma (Deception) checks (included above).\"},{\"id\":\"strixhaven-oriq-blood-mage-trait-2\",\"name\":\"Sanguine Sense\",\"description\":\"While the blood mage isn't blinded, it can see any creature that isn't an Undead or a Construct within 60 feet of itself, even through 3, 2 areas, invisibility, or any other phenomena that would prevent sight.\"}],\"actions\":[{\"id\":\"strixhaven-oriq-blood-mage-action-0\",\"name\":\"Multiattack\",\"description\":\"The blood mage makes two Blood Lash attacks.\"},{\"id\":\"strixhaven-oriq-blood-mage-action-1\",\"name\":\"Blood Lash\",\"description\":\"Melee Spell Attack: +9 to hit, reach 10 ft., one target. Hit: 21 (3d10 + 5) necrotic damage. If the target is a creature, it can't regain hit points until the start of the blood mage's next turn.\"},{\"id\":\"strixhaven-oriq-blood-mage-action-2\",\"name\":\"Blood Boil (Recharge 4-6)\",\"description\":\"The blood mage chooses a point within 150 feet of itself, and a 20-foot radius sphere centered on that point fills with a burst of searing, blood-red mist. Each creature of the blood mage's choice that it can see in that area must make a DC 17 Constitution saving throw. On a failed save, a creature takes 38 (7d10) necrotic damage and is incapacitated until the end of its next turn. On a success, a creature takes half as much damage and isn't incapacitated. A creature dies if reduced to 0 hit points by this necrotic damage.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common plus any four languages\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-oriq-recruiter\",\"name\":\"Oriq Recruiter\",\"description\":\"Oriq Recruiter from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Medium\",\"type\":\"humanoid\",\"alignment\":\"L E\",\"ac\":16,\"hp\":{\"average\":55,\"formula\":\"10d8 + 10\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":10,\"dexterity\":14,\"constitution\":12,\"intelligence\":17,\"wisdom\":15,\"charisma\":18},\"challengeRating\":\"4\",\"savingThrows\":[\"Int +5\",\"Wis +4\",\"Cha +6\"],\"skills\":[\"Arcana +5\",\"Deception +8\",\"Insight +4\",\"Persuasion +6\"],\"damageResistances\":[\"psychic\"],\"conditionImmunities\":[\"charmed\",\"frightened\"],\"senses\":[\"passive Perception 12\"],\"traits\":[{\"id\":\"strixhaven-oriq-recruiter-trait-0\",\"name\":\"Misdirecting Defense\",\"description\":\"The AC of the recruiter includes its Charisma modifier while it isn't wearing armor or wielding a shield.\"},{\"id\":\"strixhaven-oriq-recruiter-trait-1\",\"name\":\"Oriq Mask\",\"description\":\"The recruiter wears an Oriq mask. While wearing the mask, the recruiter can't be targeted by any divination magic or perceived through magical scrying sensors, and it adds double its proficiency bonus to Charisma (Deception) checks (included above).\"}],\"actions\":[{\"id\":\"strixhaven-oriq-recruiter-action-0\",\"name\":\"Multiattack\",\"description\":\"The recruiter makes two Psychic Knife attacks. It can use Spellcasting in place of one of the attacks.\"},{\"id\":\"strixhaven-oriq-recruiter-action-1\",\"name\":\"Psychic Knife\",\"description\":\"Melee or Ranged Spell Attack: +6 to hit, reach 5 ft. or range 30 ft., one creature. Hit: 21 (5d6 + 4) psychic damage.\"},{\"id\":\"strixhaven-oriq-recruiter-spellcasting-0\",\"name\":\"Spellcasting\",\"description\":\"The recruiter casts one of the following spells, requiring no material components and using Charisma as the spellcasting ability (spell save DC 14):\\n\\n- At will: disguise self, silent image\\n- 1/day: suggestion\\n- 2/day: charm person\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common plus any two languages\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-pest-mascot\",\"name\":\"Pest Mascot\",\"description\":\"Pest Mascot from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Tiny\",\"type\":\"monstrosity\",\"alignment\":\"U\",\"ac\":13,\"hp\":{\"average\":22,\"formula\":\"4d4 + 12\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":11,\"dexterity\":14,\"constitution\":17,\"intelligence\":5,\"wisdom\":13,\"charisma\":4},\"challengeRating\":\"1/4\",\"skills\":[\"Perception +3\"],\"senses\":[\"darkvision 60 ft., passive Perception 13\"],\"traits\":[{\"id\":\"strixhaven-pest-mascot-trait-0\",\"name\":\"Regeneration\",\"description\":\"The pest regains 5 hit points at the start of its turn if it has at least 1 hit point. If it takes fire damage, this trait doesn't function at the start of the pest's next turn.\"},{\"id\":\"strixhaven-pest-mascot-trait-1\",\"name\":\"Spiny Hide\",\"description\":\"At the start of each of its turns, the pest deals 2 (1d4) piercing damage to any creature grappling it or that it is grappling.\"}],\"actions\":[{\"id\":\"strixhaven-pest-mascot-action-0\",\"name\":\"Bite\",\"description\":\"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 4 (1d4 + 2) piercing damage.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-prismari-apprentice\",\"name\":\"Prismari Apprentice\",\"description\":\"Prismari Apprentice from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Small\",\"type\":\"humanoid\",\"alignment\":\"A\",\"ac\":12,\"hp\":{\"average\":44,\"formula\":\"8d8 + 8\"},\"speed\":\"35 ft.\",\"abilityScores\":{\"strength\":10,\"dexterity\":14,\"constitution\":13,\"intelligence\":12,\"wisdom\":13,\"charisma\":15},\"challengeRating\":\"2\",\"savingThrows\":[\"Dex +4\",\"Cha +4\"],\"skills\":[\"Acrobatics +4\",\"Athletics +4\",\"Performance +6\"],\"senses\":[\"passive Perception 11\"],\"traits\":[],\"actions\":[{\"id\":\"strixhaven-prismari-apprentice-action-0\",\"name\":\"Elemental Strike\",\"description\":\"Melee or Ranged Spell Attack: +4 to hit, reach 5 ft. or range 60 ft., one target. Hit: 10 (3d6) fire or cold damage (the apprentice's choice).\"},{\"id\":\"strixhaven-prismari-apprentice-spellcasting-0\",\"name\":\"Spellcasting\",\"description\":\"The apprentice casts one of the following spells, requiring no material components and using Charisma as the spellcasting ability (spell save DC 12):\\n\\n- At will: minor illusion\\n- 1/day each: gust of wind, mage armor, silent image\"}],\"bonusActions\":[{\"id\":\"strixhaven-prismari-apprentice-bonus-0\",\"name\":\"Surge of Artistry (Recharge 4-6)\",\"description\":\"The apprentice moves up to its speed, surrounding itself with elemental magic as it moves. Until the end of its turn, the apprentice can move through the space of other creatures. The first time the apprentice enters a creature's space on a turn, that creature must succeed on a DC 12 Dexterity saving throw or be knocked prone. If the apprentice ends its turn in another creature's space, the apprentice takes 5 (1d10) force damage and is pushed into the nearest unoccupied space.\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common plus any two languages\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-prismari-pledgemage\",\"name\":\"Prismari Pledgemage\",\"description\":\"Prismari Pledgemage from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Small\",\"type\":\"humanoid\",\"alignment\":\"A\",\"ac\":12,\"hp\":{\"average\":66,\"formula\":\"12d8 + 12\"},\"speed\":\"35 ft.\",\"abilityScores\":{\"strength\":10,\"dexterity\":15,\"constitution\":13,\"intelligence\":12,\"wisdom\":14,\"charisma\":17},\"challengeRating\":\"4\",\"savingThrows\":[\"Dex +4\",\"Cha +5\"],\"skills\":[\"Acrobatics +4\",\"Athletics +4\",\"Performance +7\"],\"senses\":[\"passive Perception 12\"],\"traits\":[{\"id\":\"strixhaven-prismari-pledgemage-trait-0\",\"name\":\"Evasion\",\"description\":\"If the pledgemage is subjected to an effect that allows it to make a Dexterity saving throw to take only half damage, the pledgemage instead takes no damage if it succeeds on the saving throw and only half damage if it fails, provided it isn't incapacitated.\"}],\"actions\":[{\"id\":\"strixhaven-prismari-pledgemage-action-0\",\"name\":\"Multiattack\",\"description\":\"The pledgemage makes two Elemental Strike attacks.\"},{\"id\":\"strixhaven-prismari-pledgemage-action-1\",\"name\":\"Elemental Strike\",\"description\":\"Melee or Ranged Spell Attack: +5 to hit, reach 5 ft. or range 60 ft., one target. Hit: 12 (3d6 + 2) fire or cold damage (the pledgemage's choice).\"},{\"id\":\"strixhaven-prismari-pledgemage-action-2\",\"name\":\"Showstopper (1/Day)\",\"description\":\"The pledgemage shines with elemental magic, targeting one creature it can see within 60 feet of itself. The target must make a DC 13 Wisdom saving throw. On a failed save, the target takes 28 (8d6) fire or cold damage (the pledgemage's choice) and is stunned until the start of the pledgemage's next turn. On a successful save, the target takes half as much damage and isn't stunned.\"},{\"id\":\"strixhaven-prismari-pledgemage-spellcasting-0\",\"name\":\"Spellcasting\",\"description\":\"The pledgemage casts one of the following spells, requiring no material components and using Charisma as the spellcasting ability (spell save DC 13):\\n\\n- At will: minor illusion\\n- 2/day each: gust of wind, silent image\\n- 1/day each: mage armor, water walk\"}],\"bonusActions\":[{\"id\":\"strixhaven-prismari-pledgemage-bonus-0\",\"name\":\"Surge of Artistry (Recharge 4-6)\",\"description\":\"The pledgemage moves up to its speed, surrounding itself with elemental magic as it moves. Until the end of its turn, the pledgemage can move through the space of other creatures. The first time the pledgemage enters a creature's space on a turn, that creature must succeed on a DC 13 Dexterity saving throw or be knocked prone. If the pledgemage ends its turn in another creature's space, the pledgemage takes 5 (1d10) force damage and is pushed into the nearest unoccupied space.\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common plus any two languages\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-prismari-professor-of-expression\",\"name\":\"Prismari Professor of Expression\",\"description\":\"Prismari Professor of Expression from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Small\",\"type\":\"humanoid\",\"alignment\":\"A\",\"ac\":13,\"hp\":{\"average\":97,\"formula\":\"15d8 + 30\"},\"speed\":\"40 ft.\",\"abilityScores\":{\"strength\":14,\"dexterity\":16,\"constitution\":15,\"intelligence\":15,\"wisdom\":13,\"charisma\":19},\"challengeRating\":\"7\",\"savingThrows\":[\"Dex +6\",\"Int +5\",\"Wis +4\",\"Cha +7\"],\"skills\":[\"Acrobatics +6\",\"Arcana +5\",\"Athletics +5\",\"Perception +4\",\"Performance +10\"],\"damageResistances\":[\"fire\",\"lightning\"],\"senses\":[\"passive Perception 14\"],\"traits\":[],\"actions\":[{\"id\":\"strixhaven-prismari-professor-of-expression-action-0\",\"name\":\"Multiattack\",\"description\":\"The professor makes three Cinder Strike attacks.\"},{\"id\":\"strixhaven-prismari-professor-of-expression-action-1\",\"name\":\"Cinder Strike\",\"description\":\"Melee Spell Attack: +7 to hit, reach 15 ft., one target. Hit: 13 (2d8 + 4) fire damage.\"},{\"id\":\"strixhaven-prismari-professor-of-expression-action-2\",\"name\":\"Lightning Flourish (Recharge 6)\",\"description\":\"The professor unleashes arcs of magical lightning at up to two creatures it can see within 60 feet of itself. Each target must make a DC 15 Dexterity saving throw, taking 35 (10d6) lightning damage on a failed save, or half as much damage on a successful one.\"},{\"id\":\"strixhaven-prismari-professor-of-expression-spellcasting-0\",\"name\":\"Spellcasting\",\"description\":\"The professor casts one of the following spells, requiring no material components and using Charisma as the spellcasting ability (spell save DC 15):\\n\\n- At will: minor illusion\\n- 2/day each: fog cloud, gust of wind, mage armor\"}],\"bonusActions\":[{\"id\":\"strixhaven-prismari-professor-of-expression-bonus-0\",\"name\":\"Flaming Leap\",\"description\":\"The professor is wreathed in flames and jumps up to 30 feet in any direction. When the professor lands, the flames erupt in a 10-foot radius around the professor and then vanish. Each creature of the professor's choice in that area must succeed on a DC 15 Dexterity saving throw or take 7 (2d6) fire damage.\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common plus any four languages\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-prismari-professor-of-perfection\",\"name\":\"Prismari Professor of Perfection\",\"description\":\"Prismari Professor of Perfection from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Small\",\"type\":\"humanoid\",\"alignment\":\"A\",\"ac\":13,\"hp\":{\"average\":97,\"formula\":\"15d8 + 30\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":14,\"dexterity\":16,\"constitution\":15,\"intelligence\":15,\"wisdom\":13,\"charisma\":19},\"challengeRating\":\"7\",\"savingThrows\":[\"Dex +6\",\"Int +5\",\"Wis +4\",\"Cha +7\"],\"skills\":[\"Acrobatics +6\",\"Arcana +5\",\"Athletics +5\",\"Perception +4\",\"Performance +10\"],\"damageResistances\":[\"cold\"],\"senses\":[\"passive Perception 14\"],\"traits\":[{\"id\":\"strixhaven-prismari-professor-of-perfection-trait-0\",\"name\":\"Water Walking\",\"description\":\"The professor can walk across water and other liquids as if they were solid ground.\"}],\"actions\":[{\"id\":\"strixhaven-prismari-professor-of-perfection-action-0\",\"name\":\"Multiattack\",\"description\":\"The professor makes three Tidal Strike attacks.\"},{\"id\":\"strixhaven-prismari-professor-of-perfection-action-1\",\"name\":\"Tidal Strike\",\"description\":\"Melee or Ranged Spell Attack: +7 to hit, reach 5 ft. or range 60 ft., one target. Hit: 13 (2d8 + 4) cold damage.\"},{\"id\":\"strixhaven-prismari-professor-of-perfection-spellcasting-0\",\"name\":\"Spellcasting\",\"description\":\"The professor casts one of the following spells, requiring no material components and using Charisma as the spellcasting ability (spell save DC 15):\\n\\n- At will: minor illusion\\n- 1/day: wall of ice\\n- 2/day each: control water, create or destroy water, mage armor, stone shape\"}],\"bonusActions\":[{\"id\":\"strixhaven-prismari-professor-of-perfection-bonus-0\",\"name\":\"Rushing Wave\",\"description\":\"The professor is momentarily surrounded by a swirling wave of water and moves up to 30 feet. When the professor moves within 5 feet of any other creature during this bonus action, that creature must succeed on a DC 15 Strength saving throw, or the creature is knocked prone and it can't take reactions until the start of its next turn. A creature can suffer this effect only once during a turn.\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common plus any four languages\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-quandrix-apprentice\",\"name\":\"Quandrix Apprentice\",\"description\":\"Quandrix Apprentice from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Small\",\"type\":\"humanoid\",\"alignment\":\"A\",\"ac\":11,\"hp\":{\"average\":44,\"formula\":\"8d8 + 8\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":10,\"dexterity\":12,\"constitution\":13,\"intelligence\":15,\"wisdom\":14,\"charisma\":11},\"challengeRating\":\"2\",\"savingThrows\":[\"Int +4\",\"Wis +4\"],\"skills\":[\"Arcana +6\",\"Investigation +6\",\"Nature +4\"],\"senses\":[\"passive Perception 12\"],\"traits\":[],\"actions\":[{\"id\":\"strixhaven-quandrix-apprentice-action-0\",\"name\":\"Multiattack\",\"description\":\"The apprentice makes two Exponential Lash attacks.\"},{\"id\":\"strixhaven-quandrix-apprentice-action-1\",\"name\":\"Exponential Lash\",\"description\":\"Melee or Ranged Spell Attack: +4 to hit, reach 5 ft. or range 60 ft., one target. Hit: 5 (1d6 + 2) force damage, and the apprentice can cause one creature it can see within 30 feet of the target to take 9 (2d6 + 2) force damage.\"},{\"id\":\"strixhaven-quandrix-apprentice-spellcasting-0\",\"name\":\"Spellcasting\",\"description\":\"The apprentice casts one of the following spells, requiring no material components and using Intelligence as the spellcasting ability (spell save DC 12):\\n\\n- At will: guidance, mage hand\\n- 1/day each: enlarge/reduce, mage armor\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common plus any two languages\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-quandrix-pledgemage\",\"name\":\"Quandrix Pledgemage\",\"description\":\"Quandrix Pledgemage from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Small\",\"type\":\"humanoid\",\"alignment\":\"A\",\"ac\":12,\"hp\":{\"average\":66,\"formula\":\"12d8 + 12\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":10,\"dexterity\":14,\"constitution\":13,\"intelligence\":17,\"wisdom\":14,\"charisma\":11},\"challengeRating\":\"4\",\"savingThrows\":[\"Int +5\",\"Wis +4\"],\"skills\":[\"Arcana +7\",\"Investigation +7\",\"Nature +5\"],\"senses\":[\"passive Perception 12\"],\"traits\":[],\"actions\":[{\"id\":\"strixhaven-quandrix-pledgemage-action-0\",\"name\":\"Multiattack\",\"description\":\"The pledgemage makes two Exponential Lash attacks.\"},{\"id\":\"strixhaven-quandrix-pledgemage-action-1\",\"name\":\"Exponential Lash\",\"description\":\"Melee or Ranged Spell Attack: +5 to hit, reach 5 ft. or range 60 ft., one target. Hit: 6 (1d6 + 3) force damage, and the pledgemage can cause one creature it can see within 30 feet of the target to take 10 (2d6 + 3) force damage.\"},{\"id\":\"strixhaven-quandrix-pledgemage-spellcasting-0\",\"name\":\"Spellcasting\",\"description\":\"The pledgemage casts one of the following spells, requiring no material components and using Intelligence as the spellcasting ability (spell save DC 13):\\n\\n- At will: guidance, mage hand\\n- 1/day each: dimension door, enlarge/reduce, mage armor, plant growth\"}],\"bonusActions\":[{\"id\":\"strixhaven-quandrix-pledgemage-bonus-0\",\"name\":\"Vortex Calculus (Recharge 4-6)\",\"description\":\"The pledgemage teleports, along with any equipment it is wearing or carrying, to an unoccupied space it can see within 60 feet of itself. Immediately after it teleports, each creature within 20 feet of the space it left must make a DC 13 Constitution saving throw. On a failed save, a creature takes 7 (2d6) force damage and is moved 10 feet in a random horizontal direction. On a successful save, a creature takes half as much damage and isn't moved.\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common plus any two languages\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-quandrix-professor-of-substance\",\"name\":\"Quandrix Professor of Substance\",\"description\":\"Quandrix Professor of Substance from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Small\",\"type\":\"humanoid\",\"alignment\":\"A\",\"ac\":12,\"hp\":{\"average\":104,\"formula\":\"16d8 + 32\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":11,\"dexterity\":14,\"constitution\":14,\"intelligence\":19,\"wisdom\":14,\"charisma\":13},\"challengeRating\":\"7\",\"savingThrows\":[\"Con +5\",\"Int +7\",\"Wis +5\",\"Cha +4\"],\"skills\":[\"Arcana +10\",\"Investigation +10\",\"Nature +7\",\"Perception +5\"],\"damageResistances\":[\"force\"],\"senses\":[\"passive Perception 15\"],\"traits\":[],\"actions\":[{\"id\":\"strixhaven-quandrix-professor-of-substance-action-0\",\"name\":\"Multiattack\",\"description\":\"The professor makes two Spatial Blade attacks.\"},{\"id\":\"strixhaven-quandrix-professor-of-substance-action-1\",\"name\":\"Spatial Blade\",\"description\":\"Melee or Ranged Spell Attack: +7 to hit (the target can't benefit from cover less than 3), reach 5 ft. or range 120 ft., one target. Hit: 13 (2d8 + 4) force damage, or 22 (4d8 + 4) force damage if the professor is Large or larger, and the professor can push the target horizontally up to 10 feet away.\"},{\"id\":\"strixhaven-quandrix-professor-of-substance-spellcasting-0\",\"name\":\"Spellcasting\",\"description\":\"The professor casts one of the following spells, requiring no material components and using Intelligence as the spellcasting ability (spell save DC 15):\\n\\n- At will: guidance, mage hand, mending (as an action)\\n- 1/day each: creation (as an action), dimension door, mage armor, plant growth, polymorph\"}],\"bonusActions\":[{\"id\":\"strixhaven-quandrix-professor-of-substance-bonus-0\",\"name\":\"Dilation (Recharge 5-6)\",\"description\":\"The professor magically alters its physical form until it uses this bonus action again, until it is incapacitated or dies, or until it dismisses the effect (no action required). Choose one of the following options:\"},{\"id\":\"strixhaven-quandrix-professor-of-substance-bonus-1\",\"name\":\"Expand\",\"description\":\"The professor becomes Large if there is sufficient room for it to grow. It has advantage on attack rolls and on ability checks and saving throws that rely on Strength.\"},{\"id\":\"strixhaven-quandrix-professor-of-substance-bonus-2\",\"name\":\"Contract\",\"description\":\"The professor becomes Small. Its walking speed increases to 60 feet, attack rolls against it have disadvantage, and it has advantage on ability checks and saving throws that rely on Dexterity.\"}],\"reactions\":[{\"id\":\"strixhaven-quandrix-professor-of-substance-reaction-0\",\"name\":\"Avoidant Translation (2/Day)\",\"description\":\"When the professor is hit by an attack roll, it can increase its AC by 3 against that attack, potentially causing it to miss. The professor can then teleport, along with any equipment it is wearing or carrying, up to 30 feet to an unoccupied space it can see.\"}],\"legendaryActions\":[],\"languages\":[\"Common plus any four languages\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-quandrix-professor-of-theory\",\"name\":\"Quandrix Professor of Theory\",\"description\":\"Quandrix Professor of Theory from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Small\",\"type\":\"humanoid\",\"alignment\":\"A\",\"ac\":12,\"hp\":{\"average\":97,\"formula\":\"15d8 + 30\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":11,\"dexterity\":14,\"constitution\":14,\"intelligence\":19,\"wisdom\":15,\"charisma\":13},\"challengeRating\":\"7\",\"savingThrows\":[\"Con +5\",\"Int +7\",\"Wis +5\",\"Cha +4\"],\"skills\":[\"Arcana +10\",\"Insight +5\",\"Investigation +10\",\"Perception +5\"],\"damageResistances\":[\"psychic\"],\"conditionImmunities\":[\"charmed\",\"frightened\"],\"senses\":[\"passive Perception 15\"],\"traits\":[],\"actions\":[{\"id\":\"strixhaven-quandrix-professor-of-theory-action-0\",\"name\":\"Multiattack\",\"description\":\"The professor makes two Heuristic Lance attacks. It can also use Overriding Theorem, if available.\"},{\"id\":\"strixhaven-quandrix-professor-of-theory-action-1\",\"name\":\"Heuristic Lance\",\"description\":\"Melee or Ranged Spell Attack: +7 to hit, reach 5 ft. or range 60 ft., one creature. Hit: 13 (2d8 + 4) psychic damage, and the target is poisoned until the end of its next turn.\"},{\"id\":\"strixhaven-quandrix-professor-of-theory-action-2\",\"name\":\"Overriding Theorem (Recharge 4-6)\",\"description\":\"The professor magically influences the mind of up to two creatures it can see within 60 feet of itself. Each target must succeed on a DC 15 Intelligence saving throw or become charmed by the professor until the start of the professor's next turn. The charmed creature must immediately use its reaction, if available, to move up its speed toward another creature of the professor's choice and make one melee attack against that other creature.\"},{\"id\":\"strixhaven-quandrix-professor-of-theory-spellcasting-0\",\"name\":\"Spellcasting\",\"description\":\"The professor casts one of the following spells, requiring no material components and using Intelligence as the spellcasting ability (spell save DC 15):\\n\\n- At will: guidance, mage hand, minor illusion\\n- 1/day each: mage armor, major image, mirage arcane (as an action), Rary's telepathic bond\"}],\"bonusActions\":[],\"reactions\":[{\"id\":\"strixhaven-quandrix-professor-of-theory-reaction-0\",\"name\":\"Divide by Zero (2/Day)\",\"description\":\"When the professor sees another creature within 60 feet of itself casting a spell, the professor can try to nullify the spell's formation. The creature must succeed on a DC 15 saving throw using the spell's spellcasting ability, or the spell fails and is wasted.\"}],\"legendaryActions\":[],\"languages\":[\"Common plus any four languages\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-relic-sloth\",\"name\":\"Relic Sloth\",\"description\":\"Relic Sloth from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Huge\",\"type\":\"beast\",\"alignment\":\"U\",\"ac\":13,\"hp\":{\"average\":76,\"formula\":\"8d12 + 24\"},\"speed\":\"20 ft., climb 20 ft.\",\"abilityScores\":{\"strength\":20,\"dexterity\":9,\"constitution\":17,\"intelligence\":2,\"wisdom\":12,\"charisma\":8},\"challengeRating\":\"2\",\"skills\":[\"Perception +3\"],\"senses\":[\"passive Perception 13\"],\"traits\":[],\"actions\":[{\"id\":\"strixhaven-relic-sloth-action-0\",\"name\":\"Claws\",\"description\":\"Melee Weapon Attack: +7 to hit, reach 10 ft., one target. Hit: 14 (2d8 + 5) slashing damage, and the target is grappled (escape DC 15). The relic sloth can grapple no more than two targets at a time.\"}],\"bonusActions\":[],\"reactions\":[{\"id\":\"strixhaven-relic-sloth-reaction-0\",\"name\":\"Slow but Sturdy\",\"description\":\"When the relic sloth is subjected to an effect that would move it out of its current space or knock it prone, it is neither moved nor knocked prone.\"}],\"legendaryActions\":[],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-ruin-grinder\",\"name\":\"Ruin Grinder\",\"description\":\"Ruin Grinder from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Large\",\"type\":\"construct\",\"alignment\":\"U\",\"ac\":16,\"hp\":{\"average\":82,\"formula\":\"11d10 + 22\"},\"speed\":\"30 ft., burrow 30 ft.\",\"abilityScores\":{\"strength\":22,\"dexterity\":13,\"constitution\":15,\"intelligence\":3,\"wisdom\":10,\"charisma\":1},\"challengeRating\":\"5\",\"damageImmunities\":[\"fire\",\"poison\"],\"conditionImmunities\":[\"charmed\",\"exhaustion\",\"frightened\",\"petrified\",\"poisoned\"],\"senses\":[\"blindsight 60 ft. (blind beyond this radius), passive Perception 10\"],\"traits\":[{\"id\":\"strixhaven-ruin-grinder-trait-0\",\"name\":\"Fire Absorption\",\"description\":\"Whenever the ruin grinder is subjected to fire damage, it regains a number of hit points equal to half the fire damage dealt.\"},{\"id\":\"strixhaven-ruin-grinder-trait-1\",\"name\":\"Siege Monster\",\"description\":\"The ruin grinder deals double damage to objects and structures.\"},{\"id\":\"strixhaven-ruin-grinder-trait-2\",\"name\":\"Tunneler\",\"description\":\"The ruin grinder can burrow through solid rock at half its burrowing speed and leaves a 10-foot-diameter tunnel in its wake.\"}],\"actions\":[{\"id\":\"strixhaven-ruin-grinder-action-0\",\"name\":\"Multiattack\",\"description\":\"The ruin grinder makes two Excavator attacks.\"},{\"id\":\"strixhaven-ruin-grinder-action-1\",\"name\":\"Excavator\",\"description\":\"Melee Weapon Attack: +9 to hit, reach 5 ft., one target. Hit: 13 (2d6 + 6) force damage. If the target is a Huge or smaller creature, it must succeed on a DC 17 Strength saving throw or be pushed up to 10 feet away and knocked prone.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"understands the languages of its creator but can't speak\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-scufflecup-teacup\",\"name\":\"Scufflecup Teacup\",\"description\":\"Scufflecup Teacup from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Tiny\",\"type\":\"construct\",\"alignment\":\"U\",\"ac\":12,\"hp\":{\"average\":5,\"formula\":\"2d4\"},\"speed\":\"20 ft.\",\"abilityScores\":{\"strength\":4,\"dexterity\":14,\"constitution\":10,\"intelligence\":3,\"wisdom\":3,\"charisma\":1},\"challengeRating\":\"0\",\"damageImmunities\":[\"poison\"],\"conditionImmunities\":[\"blinded\",\"exhaustion\",\"poisoned\"],\"senses\":[\"blindsight 30 ft. (blind beyond this radius), passive Perception 6\"],\"traits\":[],\"actions\":[{\"id\":\"strixhaven-scufflecup-teacup-action-0\",\"name\":\"Slam\",\"description\":\"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 3 (1d3 + 2) bludgeoning damage.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-shadrix-silverquill\",\"name\":\"Shadrix Silverquill\",\"description\":\"Shadrix Silverquill from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Gargantuan\",\"type\":\"dragon\",\"alignment\":\"N\",\"ac\":21,\"hp\":{\"average\":363,\"formula\":\"22d20 + 132\"},\"speed\":\"40 ft., fly 80 ft.\",\"abilityScores\":{\"strength\":25,\"dexterity\":14,\"constitution\":23,\"intelligence\":18,\"wisdom\":18,\"charisma\":26},\"challengeRating\":\"22\",\"savingThrows\":[\"Dex +9\",\"Con +13\",\"Wis +11\",\"Cha +15\"],\"skills\":[\"Arcana +18\",\"Deception +15\",\"Perception +11\",\"Persuasion +15\"],\"damageImmunities\":[\"psychic\",\"radiant\"],\"senses\":[\"blindsight 120 ft., passive Perception 21\"],\"traits\":[{\"id\":\"strixhaven-shadrix-silverquill-trait-0\",\"name\":\"Legendary Resistance (3/Day)\",\"description\":\"If Shadrix fails a saving throw, he can choose to succeed instead.\"}],\"actions\":[{\"id\":\"strixhaven-shadrix-silverquill-action-0\",\"name\":\"Multiattack\",\"description\":\"Shadrix makes one Bite attack and two Claw attacks.\"},{\"id\":\"strixhaven-shadrix-silverquill-action-1\",\"name\":\"Bite\",\"description\":\"Melee Weapon Attack: +14 to hit, reach 15 ft., one target. Hit: 12 (1d10 + 7) piercing damage plus 4 (1d8) radiant damage.\"},{\"id\":\"strixhaven-shadrix-silverquill-action-2\",\"name\":\"Claw\",\"description\":\"Melee Weapon Attack: +14 to hit, reach 10 ft., one target. Hit: 10 (1d6 + 7) slashing damage. If the target is a creature, it is wracked with despair and has disadvantage on attack rolls until the end of its next turn.\"},{\"id\":\"strixhaven-shadrix-silverquill-action-3\",\"name\":\"Illuminating Shadow Breath (Recharge 5-6)\",\"description\":\"Shadrix exhales an entwined burst of blinding radiance and unnerving shadow in a 90-foot cone. Each creature in that area must make a DC 21 Constitution saving throw. On a failed save, a creature takes 31 (7d8) radiant damage and 31 (7d8) psychic damage and is blinded until the start of Shadrix's next turn. On a successful save, a creature takes half as much damage and isn't blinded.\"},{\"id\":\"strixhaven-shadrix-silverquill-spellcasting-0\",\"name\":\"Spellcasting\",\"description\":\"Shadrix casts one of the following spells, requiring no material components and using Charisma as the spellcasting ability (spell save DC 23):\\n\\n- 1/day each: darkness, daylight, hypnotic pattern, sending, suggestion\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[{\"id\":\"strixhaven-shadrix-silverquill-legendary-0\",\"name\":\"Claw\",\"description\":\"Shadrix makes one Claw attack.\"},{\"id\":\"strixhaven-shadrix-silverquill-legendary-1\",\"name\":\"Shadow Slip (Costs 2 Actions)\",\"description\":\"Shadrix becomes an inky cloud of shadow and can move up to half his flying speed without provoking opportunity attacks, then resumes his true form. During this movement, he can move through creatures and objects as if they were 3. If he moves through a creature, it must succeed on a DC 21 Constitution saving throw or become blinded until the end of its next turn. If Shadrix ends this move inside an object, he takes 5 (1d10) force damage and is shunted to the nearest unoccupied space.\"},{\"id\":\"strixhaven-shadrix-silverquill-legendary-2\",\"name\":\"Flash of Inspiration (Costs 3 Actions)\",\"description\":\"Shadrix magically summons 1d4 inkling mascots in unoccupied spaces he can see within 60 feet of himself. The inklings obey his commands and take their turns immediately after his. While any of these inklings live, Shadrix has advantage on attack rolls and saving throws. These inklings disappear after 10 minutes, when Shadrix dies, or when he uses this action again.\"}],\"languages\":[\"all\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-silverquill-apprentice\",\"name\":\"Silverquill Apprentice\",\"description\":\"Silverquill Apprentice from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Small\",\"type\":\"humanoid\",\"alignment\":\"A\",\"ac\":12,\"hp\":{\"average\":44,\"formula\":\"8d8 + 8\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":10,\"dexterity\":14,\"constitution\":13,\"intelligence\":12,\"wisdom\":11,\"charisma\":15},\"challengeRating\":\"2\",\"savingThrows\":[\"Dex +4\",\"Cha +4\"],\"skills\":[\"Deception +4\",\"Performance +6\",\"Persuasion +6\"],\"senses\":[\"passive Perception 10\"],\"traits\":[],\"actions\":[{\"id\":\"strixhaven-silverquill-apprentice-action-0\",\"name\":\"Ink Blade\",\"description\":\"Melee or Ranged Spell Attack: +4 to hit, reach 5 ft. or range 60 ft., one target. Hit: 5 (1d6 + 2) piercing damage plus 9 (2d8) psychic damage.\"},{\"id\":\"strixhaven-silverquill-apprentice-spellcasting-0\",\"name\":\"Spellcasting\",\"description\":\"The apprentice casts one of the following spells, requiring no material components and using Charisma as the spellcasting ability (spell save DC 12):\\n\\n- At will: dancing lights, friends\\n- 1/day each: command, mage armor\"}],\"bonusActions\":[],\"reactions\":[{\"id\":\"strixhaven-silverquill-apprentice-reaction-0\",\"name\":\"Rousing Verse\",\"description\":\"When a creature the apprentice can see within 30 feet of it fails a saving throw, the apprentice magically weaves together stirring prose, allowing the creature to reroll the saving throw and use the higher result.\"}],\"legendaryActions\":[],\"languages\":[\"Common plus any two languages\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-silverquill-pledgemage\",\"name\":\"Silverquill Pledgemage\",\"description\":\"Silverquill Pledgemage from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Small\",\"type\":\"humanoid\",\"alignment\":\"A\",\"ac\":13,\"hp\":{\"average\":66,\"formula\":\"12d8 + 12\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":10,\"dexterity\":16,\"constitution\":13,\"intelligence\":12,\"wisdom\":11,\"charisma\":17},\"challengeRating\":\"4\",\"savingThrows\":[\"Dex +5\",\"Wis +2\",\"Cha +5\"],\"skills\":[\"Deception +5\",\"Performance +7\",\"Persuasion +7\"],\"senses\":[\"passive Perception 10\"],\"traits\":[],\"actions\":[{\"id\":\"strixhaven-silverquill-pledgemage-action-0\",\"name\":\"Ink Blade\",\"description\":\"Melee or Ranged Spell Attack: +5 to hit, reach 5 ft. or range 60 ft., one target. Hit: 5 (1d8 + 3) piercing damage plus 10 (3d6) psychic damage.\"},{\"id\":\"strixhaven-silverquill-pledgemage-spellcasting-0\",\"name\":\"Spellcasting\",\"description\":\"The pledgemage casts one of the following spells, requiring no material components and using Charisma as the spellcasting ability (spell save DC 13):\\n\\n- At will: dancing lights, friends\\n- 1/day each: command, confusion, mage armor, tongues\"}],\"bonusActions\":[{\"id\":\"strixhaven-silverquill-pledgemage-bonus-0\",\"name\":\"Demotivate (2/Day)\",\"description\":\"The pledgemage hurls magical insults at one creature it can see within 30 feet of itself. The target must succeed on a DC 13 Wisdom saving throw or become frightened of the pledgemage for 1 minute. While frightened in this way, the target can't take reactions, its speed is halved, and any hit the pledgemage scores against the creature is a critical hit. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.\"}],\"reactions\":[{\"id\":\"strixhaven-silverquill-pledgemage-reaction-0\",\"name\":\"Rousing Verse\",\"description\":\"When a creature the pledgemage can see within 30 feet of it fails a saving throw, the pledgemage magically weaves together stirring prose, allowing the creature to reroll the saving throw and use the higher result.\"}],\"legendaryActions\":[],\"languages\":[\"Common plus any two languages\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-silverquill-professor-of-radiance\",\"name\":\"Silverquill Professor of Radiance\",\"description\":\"Silverquill Professor of Radiance from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Small\",\"type\":\"humanoid\",\"alignment\":\"A\",\"ac\":12,\"hp\":{\"average\":97,\"formula\":\"15d8 + 30\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":11,\"dexterity\":14,\"constitution\":14,\"intelligence\":16,\"wisdom\":13,\"charisma\":19},\"challengeRating\":\"7\",\"savingThrows\":[\"Dex +5\",\"Int +6\",\"Wis +4\",\"Cha +7\"],\"skills\":[\"Arcana +6\",\"Deception +7\",\"Performance +10\",\"Persuasion +10\"],\"damageResistances\":[\"radiant\"],\"senses\":[\"passive Perception 11\"],\"traits\":[],\"actions\":[{\"id\":\"strixhaven-silverquill-professor-of-radiance-action-0\",\"name\":\"Multiattack\",\"description\":\"The professor makes two Radiant Strike attacks. The professor can replace one of the attacks with a use of Spellcasting.\"},{\"id\":\"strixhaven-silverquill-professor-of-radiance-action-1\",\"name\":\"Radiant Strike\",\"description\":\"Melee or Ranged Spell Attack: +7 to hit, reach 5 ft. or range 120 ft., one target. Hit: 17 (3d8 + 4) radiant damage. If the target is a creature, it must succeed on a DC 15 Constitution saving throw be blinded until the end of its next turn.\"},{\"id\":\"strixhaven-silverquill-professor-of-radiance-spellcasting-0\",\"name\":\"Spellcasting\",\"description\":\"The professor casts one of the following spells, requiring no material components and using Charisma as the spellcasting ability (spell save DC 15):\\n\\n- At will: dancing lights, friends\\n- 2/day each: bless, command, cure wounds, daylight, mage armor\\n- 1/day each: hypnotic pattern, tongues\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common plus any four languages\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-silverquill-professor-of-shadow\",\"name\":\"Silverquill Professor of Shadow\",\"description\":\"Silverquill Professor of Shadow from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Small\",\"type\":\"humanoid\",\"alignment\":\"A\",\"ac\":12,\"hp\":{\"average\":97,\"formula\":\"15d8 + 30\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":11,\"dexterity\":14,\"constitution\":14,\"intelligence\":16,\"wisdom\":13,\"charisma\":19},\"challengeRating\":\"7\",\"savingThrows\":[\"Dex +5\",\"Int +6\",\"Wis +4\",\"Cha +7\"],\"skills\":[\"Arcana +6\",\"Deception +10\",\"Persuasion +7\",\"Stealth +5\"],\"damageResistances\":[\"necrotic\"],\"senses\":[\"darkvision 300 ft., passive Perception 11\"],\"traits\":[{\"id\":\"strixhaven-silverquill-professor-of-shadow-trait-0\",\"name\":\"Devil's Sight\",\"description\":\"Magical darkness doesn't impede the professor's darkvision.\"}],\"actions\":[{\"id\":\"strixhaven-silverquill-professor-of-shadow-action-0\",\"name\":\"Multiattack\",\"description\":\"The professor makes two Ink Lance attacks. The professor can replace one of the attacks with a use of Spellcasting.\"},{\"id\":\"strixhaven-silverquill-professor-of-shadow-action-1\",\"name\":\"Ink Lance\",\"description\":\"Melee or Ranged Spell Attack: +7 to hit, reach 5 ft. or range 120 ft., one target. Hit: 17 (3d8 + 4) necrotic damage. If the target is a creature, it must succeed on a DC 15 Constitution saving throw be blinded until the end of its next turn.\"},{\"id\":\"strixhaven-silverquill-professor-of-shadow-spellcasting-0\",\"name\":\"Spellcasting\",\"description\":\"The professor casts one of the following spells, requiring no material components and using Charisma as the spellcasting ability (spell save DC 15):\\n\\n- At will: dancing lights, friends\\n- 2/day each: bane, command, darkness, mage armor\\n- 1/day each: tongues\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common plus any four languages\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-spirit-statue-mascot\",\"name\":\"Spirit Statue Mascot\",\"description\":\"Spirit Statue Mascot from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Medium\",\"type\":\"construct\",\"alignment\":\"A\",\"ac\":14,\"hp\":{\"average\":26,\"formula\":\"4d8 + 8\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":14,\"dexterity\":9,\"constitution\":15,\"intelligence\":12,\"wisdom\":13,\"charisma\":8},\"challengeRating\":\"1/4\",\"skills\":[\"Arcana +5\",\"History +5\",\"Perception +3\"],\"senses\":[\"passive Perception 13\"],\"traits\":[{\"id\":\"strixhaven-spirit-statue-mascot-trait-0\",\"name\":\"Death Burst\",\"description\":\"When the spirit statue is reduced to 0 hit points, the statue crumbles, and the spirit returns to the afterlife in a burst of ghostly white flame. Each creature within 5 feet of it must succeed on a DC 12 Constitution saving throw or take 3 (1d6) radiant damage.\"}],\"actions\":[{\"id\":\"strixhaven-spirit-statue-mascot-action-0\",\"name\":\"Slam\",\"description\":\"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 5 (1d6 + 2) bludgeoning damage.\"},{\"id\":\"strixhaven-spirit-statue-mascot-action-1\",\"name\":\"Counsel of the Past (2/Day)\",\"description\":\"The spirit statue touches one creature. Once within the next 10 minutes, that creature can roll a d4 and add the number rolled to one ability check of its choice, immediately after rolling the d20.\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"any languages it knew in life\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-strixhaven-campus-guide\",\"name\":\"Strixhaven Campus Guide\",\"description\":\"Strixhaven Campus Guide from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Small\",\"type\":\"construct\",\"alignment\":\"L G\",\"ac\":17,\"hp\":{\"average\":31,\"formula\":\"7d6 + 7\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":15,\"dexterity\":14,\"constitution\":13,\"intelligence\":10,\"wisdom\":12,\"charisma\":12},\"challengeRating\":\"1\",\"savingThrows\":[\"Dex +4\"],\"skills\":[\"Insight +3\",\"Persuasion +3\"],\"damageImmunities\":[\"poison\"],\"conditionImmunities\":[\"blinded\",\"deafened\",\"exhaustion\",\"paralyzed\",\"petrified\",\"poisoned\"],\"senses\":[\"blindsight 60 ft., passive Perception 11\"],\"traits\":[{\"id\":\"strixhaven-strixhaven-campus-guide-trait-0\",\"name\":\"Campus Knowledge\",\"description\":\"While at Strixhaven, the guide can't become lost by magical or nonmagical means. The guide also has advantage on ability checks made to locate creatures or objects at Strixhaven.\"},{\"id\":\"strixhaven-strixhaven-campus-guide-trait-1\",\"name\":\"Univocal Speech\",\"description\":\"When the guide speaks, any creature that knows at least one language and can hear the guide understands what it says.\"},{\"id\":\"strixhaven-strixhaven-campus-guide-trait-2\",\"name\":\"Unusual Nature\",\"description\":\"The guide doesn't require air, food, drink, or sleep.\"}],\"actions\":[{\"id\":\"strixhaven-strixhaven-campus-guide-action-0\",\"name\":\"Multiattack\",\"description\":\"The guide makes two Slam attacks.\"},{\"id\":\"strixhaven-strixhaven-campus-guide-action-1\",\"name\":\"Slam\",\"description\":\"Melee Weapon Attack: +4 to hit, reach 5 ft., one target. Hit: 6 (1d8 + 2) bludgeoning damage.\"},{\"id\":\"strixhaven-strixhaven-campus-guide-action-2\",\"name\":\"Smile and Wave\",\"description\":\"Each creature of the guide's choice that is within 30 feet of the guide must succeed on a DC 11 Wisdom saving throw or be magically charmed by the guide for 1 hour. A charmed target must move on its turn toward the guide, trying to get within 5 feet of the guide. The target doesn't move into obviously dangerous ground, such as a fire or a pit. Whenever the charmed target takes damage, it can repeat the saving throw, ending the effect on itself on a success. A target that successfully saves is immune to any guide's Smile and Wave ability for the next 24 hours.\"}],\"bonusActions\":[{\"id\":\"strixhaven-strixhaven-campus-guide-bonus-0\",\"name\":\"Need Directions\",\"description\":\"The guide takes the Help action.\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common plus any three languages\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-tanazir-quandrix\",\"name\":\"Tanazir Quandrix\",\"description\":\"Tanazir Quandrix from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Gargantuan\",\"type\":\"dragon\",\"alignment\":\"L N\",\"ac\":21,\"hp\":{\"average\":444,\"formula\":\"24d20 + 192\"},\"speed\":\"40 ft., fly 80 ft.\",\"abilityScores\":{\"strength\":28,\"dexterity\":14,\"constitution\":27,\"intelligence\":28,\"wisdom\":18,\"charisma\":17},\"challengeRating\":\"24\",\"savingThrows\":[\"Dex +9\",\"Con +15\",\"Wis +11\",\"Cha +10\"],\"skills\":[\"Arcana +23\",\"Investigation +23\",\"Nature +16\",\"Perception +18\"],\"damageImmunities\":[\"force\",\"psychic\"],\"senses\":[\"blindsight 120 ft., passive Perception 28\"],\"traits\":[{\"id\":\"strixhaven-tanazir-quandrix-trait-0\",\"name\":\"Legendary Resistance (3/Day)\",\"description\":\"If Tanazir fails a saving throw, she can choose to succeed instead.\"}],\"actions\":[{\"id\":\"strixhaven-tanazir-quandrix-action-0\",\"name\":\"Multiattack\",\"description\":\"Tanazir makes one Bite attack and two Claw attacks.\"},{\"id\":\"strixhaven-tanazir-quandrix-action-1\",\"name\":\"Bite\",\"description\":\"Melee Weapon Attack: +16 to hit, reach 15 ft., one target. Hit: 14 (1d10 + 9) piercing damage plus 7 (2d6) force damage.\"},{\"id\":\"strixhaven-tanazir-quandrix-action-2\",\"name\":\"Claw\",\"description\":\"Melee Weapon Attack: +16 to hit, reach 10 ft., one target. Hit: 16 (2d6 + 9) slashing damage. If the target is a creature, it is addled by recursive thoughts, reducing its speed to 0 until the start of Tanazir's next turn.\"},{\"id\":\"strixhaven-tanazir-quandrix-action-3\",\"name\":\"Diminution Breath (Recharge 5-6)\",\"description\":\"Tanazir exhales a weakening equation in a 90-foot cone. Each creature in that area must make a DC 23 Constitution saving throw. On a failed save, a creature takes 45 (13d6) force damage and 45 (13d6) psychic damage and is weakened until the start of Tanazir's next turn. While weakened, it has disadvantage on the following rolls that rely on Strength: attack rolls, ability checks, and saving throws. On a successful save, a creature takes half as much damage and isn't weakened.\"},{\"id\":\"strixhaven-tanazir-quandrix-action-4\",\"name\":\"Teleport\",\"description\":\"Tanazir teleports to an unoccupied space she can see within 100 feet of herself.\"},{\"id\":\"strixhaven-tanazir-quandrix-spellcasting-0\",\"name\":\"Spellcasting\",\"description\":\"Tanazir casts one of the following spells, requiring no material components and using Intelligence as the spellcasting ability (spell save DC 24):\\n\\n- 1/day each: divination, enlarge/reduce, mirage arcane (as an action), polymorph, scrying (as an action), seeming\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[{\"id\":\"strixhaven-tanazir-quandrix-legendary-0\",\"name\":\"Claw\",\"description\":\"Tanazir makes one Claw attack.\"},{\"id\":\"strixhaven-tanazir-quandrix-legendary-1\",\"name\":\"Fold Space (Costs 2 Actions)\",\"description\":\"Tanazir uses Teleport, and each other creature within 20 feet of the space she left must succeed on a DC 24 Strength saving throw or be pulled up to 30 feet closer to the center of that space and take 16 (3d10) force damage.\"},{\"id\":\"strixhaven-tanazir-quandrix-legendary-2\",\"name\":\"Fractal Refraction (Costs 3 Actions)\",\"description\":\"Tanazir magically summons 1d4 fractal mascots in unoccupied spaces she can see within 120 feet of herself. The fractals obey her commands and take their turns immediately after hers. While any of these fractals remain, attack rolls made against Tanazir have disadvantage. A summoned fractal disappears after 1 minute, when it or Tanazir dies, or when she uses this action again.\"}],\"languages\":[\"Common\",\"Draconic\",\"telepathy 120 ft.\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-velomachus-lorehold\",\"name\":\"Velomachus Lorehold\",\"description\":\"Velomachus Lorehold from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Gargantuan\",\"type\":\"dragon\",\"alignment\":\"L N\",\"ac\":21,\"hp\":{\"average\":487,\"formula\":\"25d20 + 225\"},\"speed\":\"40 ft., climb 40 ft., fly 80 ft.\",\"abilityScores\":{\"strength\":30,\"dexterity\":14,\"constitution\":29,\"intelligence\":30,\"wisdom\":20,\"charisma\":18},\"challengeRating\":\"25\",\"savingThrows\":[\"Dex +10\",\"Con +17\",\"Wis +13\",\"Cha +12\"],\"skills\":[\"Arcana +18\",\"History +18\",\"Investigation +18\",\"Perception +13\"],\"damageImmunities\":[\"thunder\"],\"senses\":[\"blindsight 120 ft., passive Perception 23\"],\"traits\":[{\"id\":\"strixhaven-velomachus-lorehold-trait-0\",\"name\":\"Legendary Resistance (3/Day)\",\"description\":\"If Velomachus fails a saving throw, she can choose to succeed instead.\"}],\"actions\":[{\"id\":\"strixhaven-velomachus-lorehold-action-0\",\"name\":\"Multiattack\",\"description\":\"Velomachus makes one Bite attack and two Claw attacks.\"},{\"id\":\"strixhaven-velomachus-lorehold-action-1\",\"name\":\"Bite\",\"description\":\"Melee Weapon Attack: +18 to hit, reach 15 ft., one target. Hit: 15 (1d10 + 10) piercing damage plus 6 (1d12) thunder damage.\"},{\"id\":\"strixhaven-velomachus-lorehold-action-2\",\"name\":\"Claw\",\"description\":\"Melee Weapon Attack: +18 to hit, reach 10 ft., one target. Hit: 13 (1d6 + 10) slashing damage. If the target is a Huge or smaller creature, it is knocked prone.\"},{\"id\":\"strixhaven-velomachus-lorehold-action-3\",\"name\":\"Battle Tide Breath (Recharge 5-6)\",\"description\":\"Velomachus exhales thunderous sound in a 90-foot cone. Each creature in that area must make a DC 25 Constitution saving throw. On a failure, a creature takes 45 (7d12) force damage and 45 (7d12) thunder damage and is pushed up to 20 feet in a horizontal direction of Velomachus' choice. On a success, the creature takes half as much damage and isn't pushed. Objects that aren't being worn or carried take the damage and are pushed as if they were creatures that failed the saving throw.\"},{\"id\":\"strixhaven-velomachus-lorehold-spellcasting-0\",\"name\":\"Spellcasting\",\"description\":\"Velomachus casts one of the following spells, requiring no material components and using Intelligence as the spellcasting ability:\\n\\n- 1/day each: contact other plane (as an action, contacting a long-dead spirit), divination, move earth, wall of force\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[{\"id\":\"strixhaven-velomachus-lorehold-legendary-0\",\"name\":\"Claw\",\"description\":\"Velomachus makes one Claw attack.\"},{\"id\":\"strixhaven-velomachus-lorehold-legendary-1\",\"name\":\"Chaotic Flow (Costs 2 Actions)\",\"description\":\"Velomachus moves up to half her flying speed. If a creature hits or misses her with an opportunity attack during this move, the attacker takes 19 (3d12) thunder damage.\"},{\"id\":\"strixhaven-velomachus-lorehold-legendary-2\",\"name\":\"Repeating History (Costs 3 Actions)\",\"description\":\"Velomachus magically summons 1d4 statue mascots in unoccupied spaces she can see within 60 feet of herself. The spirit statues obey her commands and take their turns immediately after hers. Any creature, other than a spirit statue or Velomachus, is restrained if it starts its turn within 5 feet of one or more of these spirit statues. This restrained condition lasts until the end of the creature's turn. These spirit statues disappear after 10 minutes, when Velomachus dies, or when she uses this action again.\"}],\"languages\":[\"all\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-witherbloom-apprentice\",\"name\":\"Witherbloom Apprentice\",\"description\":\"Witherbloom Apprentice from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Small\",\"type\":\"humanoid\",\"alignment\":\"A\",\"ac\":13,\"hp\":{\"average\":44,\"formula\":\"8d8 + 8\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":10,\"dexterity\":14,\"constitution\":13,\"intelligence\":12,\"wisdom\":15,\"charisma\":11},\"challengeRating\":\"2\",\"savingThrows\":[\"Con +3\",\"Wis +4\"],\"skills\":[\"Medicine +4\",\"Nature +5\",\"Perception +6\"],\"senses\":[\"passive Perception 16\"],\"traits\":[{\"id\":\"strixhaven-witherbloom-apprentice-trait-0\",\"name\":\"Regeneration\",\"description\":\"The apprentice regains 5 hit points at the start of its turn if it has at least 1 hit point.\"},{\"id\":\"strixhaven-witherbloom-apprentice-trait-1\",\"name\":\"Verdant Talisman\",\"description\":\"At the end of a 10-minute ritual, the apprentice can touch one willing creature (including itself) and bestow upon it a small talisman imbued with magic. Upon receiving the talisman, the creature gains 10 temporary hit points, and it can add 1d6 to its initiative rolls while it wears the talisman. These benefits last for 1 hour or until the apprentice conducts another ritual to bestow another talisman. When the benefits expire, the talisman crumbles to dust.\"}],\"actions\":[{\"id\":\"strixhaven-witherbloom-apprentice-action-0\",\"name\":\"Briar Vine\",\"description\":\"Melee Spell Attack: +4 to hit, reach 15 ft., one target. Hit: 7 (1d10 + 2) piercing damage plus 9 (2d8) poison damage. If the target is a Large or smaller creature, the apprentice can pull it up to 10 feet closer to itself.\"},{\"id\":\"strixhaven-witherbloom-apprentice-spellcasting-0\",\"name\":\"Spellcasting\",\"description\":\"The apprentice casts one of the following spells, requiring no material components and using Wisdom as the spellcasting ability:\\n\\n- At will: druidcraft, spare the dying\\n- 1/day each: pass without trace\"}],\"bonusActions\":[],\"reactions\":[{\"id\":\"strixhaven-witherbloom-apprentice-reaction-0\",\"name\":\"Wither Burst\",\"description\":\"When the apprentice sees a creature within 30 feet of itself drop to 0 hit points, the apprentice channels the expended life essence and targets another creature it can see within 30 feet of itself. The target must succeed on a DC 12 Constitution saving throw or become poisoned for 1 minute. While poisoned in this way, the target takes 3 (1d6) poison damage at the start of each of its turns. The target can repeat the save at the end of each of its turns, ending the effect on itself on a success.\"}],\"legendaryActions\":[],\"languages\":[\"Common plus any two languages\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-witherbloom-pledgemage\",\"name\":\"Witherbloom Pledgemage\",\"description\":\"Witherbloom Pledgemage from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Small\",\"type\":\"humanoid\",\"alignment\":\"A\",\"ac\":12,\"hp\":{\"average\":66,\"formula\":\"12d8 + 12\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":10,\"dexterity\":15,\"constitution\":13,\"intelligence\":14,\"wisdom\":17,\"charisma\":11},\"challengeRating\":\"4\",\"savingThrows\":[\"Con +3\",\"Wis +5\"],\"skills\":[\"Medicine +5\",\"Nature +6\",\"Perception +7\"],\"damageImmunities\":[\"poison\"],\"conditionImmunities\":[\"poisoned\"],\"senses\":[\"passive Perception 17\"],\"traits\":[{\"id\":\"strixhaven-witherbloom-pledgemage-trait-0\",\"name\":\"Regeneration\",\"description\":\"As long as the pledgemage has at least 1 hit point remaining, the pledgemage regains 5 hit points at the start of its turn.\"},{\"id\":\"strixhaven-witherbloom-pledgemage-trait-1\",\"name\":\"Verdant Talisman\",\"description\":\"At the end of a 10-minute ritual, the pledgemage can touch one willing creature (including itself) and bestow upon it a small talisman imbued with magic. Upon receiving the talisman, the creature gains 10 temporary hit points, and it can add 1d6 to its initiative rolls while it wears the talisman. These benefits last for 1 hour or until the pledgemage conducts another ritual to bestow another talisman. When the benefits expire, the talisman crumbles to dust.\"}],\"actions\":[{\"id\":\"strixhaven-witherbloom-pledgemage-action-0\",\"name\":\"Briar Vine\",\"description\":\"Melee Spell Attack: +5 to hit, reach 15 ft., one target. Hit: 8 (1d10 + 3) piercing damage plus 18 (4d8) poison damage. If the target is a Large or smaller creature, the apprentice can pull it up to 10 feet closer to itself.\"},{\"id\":\"strixhaven-witherbloom-pledgemage-spellcasting-0\",\"name\":\"Spellcasting\",\"description\":\"The apprentice casts one of the following spells, requiring no material components and using Wisdom as the spellcasting ability:\\n\\n- At will: druidcraft, spare the dying\\n- 1/day each: death ward, pass without trace, speak with plants\"}],\"bonusActions\":[{\"id\":\"strixhaven-witherbloom-pledgemage-bonus-0\",\"name\":\"Vociferous Form (1/Day)\",\"description\":\"The pledgemage transforms into an avatar of plants and shadow. While in this form, the pledgemage adds its Wisdom modifier to its AC if it isn't wearing armor or wielding a shield, and it has advantage on attack rolls against any creature missing hit points. This form lasts for 1 minute or until the pledgemage is reduced to 0 hit points.\"}],\"reactions\":[{\"id\":\"strixhaven-witherbloom-pledgemage-reaction-0\",\"name\":\"Wither Burst\",\"description\":\"When the pledgemage sees a creature within 30 feet of itself drop to 0 hit points, the pledgemage channels the expended life essence and targets another creature it can see within 30 feet of itself. The target must succeed on a DC 13 Constitution saving throw or become poisoned for 1 minute. While poisoned in this way, the target takes 3 (1d6) poison damage at the start of each of its turns. The target can repeat the save at the end of each of its turns, ending the effect on itself on a success.\"}],\"legendaryActions\":[],\"languages\":[\"Common plus any two languages\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-witherbloom-professor-of-decay\",\"name\":\"Witherbloom Professor of Decay\",\"description\":\"Witherbloom Professor of Decay from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Small\",\"type\":\"humanoid\",\"alignment\":\"A\",\"ac\":14,\"hp\":{\"average\":105,\"formula\":\"14d8 + 42\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":11,\"dexterity\":14,\"constitution\":16,\"intelligence\":16,\"wisdom\":19,\"charisma\":13},\"challengeRating\":\"7\",\"savingThrows\":[\"Con +6\",\"Int +6\",\"Wis +7\",\"Cha +4\"],\"skills\":[\"Arcana +6\",\"Medicine +7\",\"Nature +6\",\"Survival +7\"],\"damageResistances\":[\"necrotic\"],\"senses\":[\"passive Perception 14\"],\"traits\":[{\"id\":\"strixhaven-witherbloom-professor-of-decay-trait-0\",\"name\":\"Essence Transfer (1/Day)\",\"description\":\"The professor can cast the animate dead spell, using Wisdom as the spellcasting ability.\"}],\"actions\":[{\"id\":\"strixhaven-witherbloom-professor-of-decay-action-0\",\"name\":\"Multiattack\",\"description\":\"The professor makes two Mortality Spear attacks. It can replace one of the attacks with a use of Spellcasting.\"},{\"id\":\"strixhaven-witherbloom-professor-of-decay-action-1\",\"name\":\"Mortality Spear\",\"description\":\"Melee or Ranged Spell Attack: +7 to hit, reach 5 ft. or range 120 ft., one target. Hit: 17 (3d8 + 4) necrotic damage, and the target can't regain hit points until the start of the professor's next turn.\"},{\"id\":\"strixhaven-witherbloom-professor-of-decay-action-2\",\"name\":\"Essence Pulse (Recharge 5-6)\",\"description\":\"The professor creates a life-draining vortex in a 30-foot-radius sphere centered on itself. Each creature of the professor's choice that it can see within that area must make a DC 15 Constitution saving throw, taking 23 (5d8) necrotic damage on a failed save, or half as much damage on a successful one. The professor then regains 10 hit points. An affected creature's hit point maximum is reduced by an amount equal to the necrotic damage taken. This reduction lasts until the creature finishes a long rest. The creature dies if its hit point maximum is reduced to 0.\"},{\"id\":\"strixhaven-witherbloom-professor-of-decay-spellcasting-0\",\"name\":\"Spellcasting\",\"description\":\"The professor casts one of the following spells, requiring no material components and using Wisdom as the spellcasting ability (spell save DC 15):\\n\\n- At will: druidcraft, spare the dying\\n- 1/day each: antilife shell, bane, feign death, speak with dead\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common plus any four languages\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-witherbloom-professor-of-growth\",\"name\":\"Witherbloom Professor of Growth\",\"description\":\"Witherbloom Professor of Growth from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Small\",\"type\":\"humanoid\",\"alignment\":\"A\",\"ac\":13,\"hp\":{\"average\":112,\"formula\":\"15d8 + 45\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":11,\"dexterity\":13,\"constitution\":16,\"intelligence\":16,\"wisdom\":19,\"charisma\":13},\"challengeRating\":\"7\",\"savingThrows\":[\"Con +6\",\"Int +6\",\"Wis +7\",\"Cha +4\"],\"skills\":[\"Arcana +6\",\"Medicine +7\",\"Nature +6\",\"Survival +7\"],\"damageResistances\":[\"poison\"],\"conditionImmunities\":[\"poisoned\"],\"senses\":[\"passive Perception 14\"],\"traits\":[],\"actions\":[{\"id\":\"strixhaven-witherbloom-professor-of-growth-action-0\",\"name\":\"Multiattack\",\"description\":\"The professor makes two Verdant Lash attacks.\"},{\"id\":\"strixhaven-witherbloom-professor-of-growth-action-1\",\"name\":\"Verdant Lash\",\"description\":\"Melee Spell Attack: +7 to hit, reach 30 ft., one target. Hit: 11 (2d6 + 4) piercing damage plus 7 (2d6) poison damage, and the target must succeed on a DC 15 Strength saving throw or be pulled up to 10 feet closer to the professor.\"},{\"id\":\"strixhaven-witherbloom-professor-of-growth-action-2\",\"name\":\"Summon Nature's Avatar (Recharges after a Short or Long Rest)\",\"description\":\"The professor magically summons a Groff. The groff appears in an unoccupied space within 60 feet of the professor, acts as the professor's ally, and takes its turns immediately after the professor's. The professor can communicate telepathically with this groff while it remains. The groff remains for 10 minutes, until it or the professor dies, or until the professor dismisses it as an action.\"},{\"id\":\"strixhaven-witherbloom-professor-of-growth-spellcasting-0\",\"name\":\"Spellcasting\",\"description\":\"The professor casts one of the following spells, requiring no material components and using Wisdom as the spellcasting ability:\\n\\n- At will: druidcraft, spare the dying\\n- 1/day each: greater restoration, lesser restoration, mass cure wounds, pass without trace, plant growth, revivify\"}],\"bonusActions\":[],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common plus any four languages\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"},{\"id\":\"strixhaven-y-demi\",\"name\":\"Y'demi\",\"description\":\"Y'demi from Strixhaven: A Curriculum of Chaos.\",\"size\":\"Medium\",\"type\":\"humanoid\",\"alignment\":\"N E\",\"ac\":16,\"hp\":{\"average\":127,\"formula\":\"15d8 + 60\"},\"speed\":\"30 ft.\",\"abilityScores\":{\"strength\":11,\"dexterity\":14,\"constitution\":18,\"intelligence\":20,\"wisdom\":12,\"charisma\":12},\"challengeRating\":\"9\",\"savingThrows\":[\"Con +8\",\"Int +9\",\"Wis +5\",\"Cha +5\"],\"skills\":[\"Deception +9\",\"Medicine +5\",\"Survival +5\"],\"damageResistances\":[\"necrotic\"],\"conditionImmunities\":[\"exhaustion\"],\"senses\":[\"passive Perception 11\"],\"traits\":[{\"id\":\"strixhaven-y-demi-trait-0\",\"name\":\"Blood Aegis\",\"description\":\"The AC of Y'demi includes her Constitution modifier while she isn't wearing armor or wielding a shield.\"},{\"id\":\"strixhaven-y-demi-trait-1\",\"name\":\"Oriq Mask\",\"description\":\"Y'demi wears an Oriq mask. While wearing the mask, Y'demi can't be targeted by any divination magic or perceived through magical scrying sensors, and she adds double her proficiency bonus to Charisma (Deception) checks (included above).\"},{\"id\":\"strixhaven-y-demi-trait-2\",\"name\":\"Sanguine Sense\",\"description\":\"While Y'demi isn't blinded, she can see any creature that isn't an Undead or a Construct within 60 feet of itself, even through 3, 2 areas, invisibility, or any other phenomena that would prevent sight.\"}],\"actions\":[{\"id\":\"strixhaven-y-demi-action-0\",\"name\":\"Multiattack\",\"description\":\"Y'demi makes two Blood Lash attacks.\"},{\"id\":\"strixhaven-y-demi-action-1\",\"name\":\"Blood Lash\",\"description\":\"Melee Spell Attack: +9 to hit, reach 10 ft., one target. Hit: 21 (3d10 + 5) necrotic damage. If the target is a creature, it can't regain hit points until the start of the Y'demi's next turn.\"},{\"id\":\"strixhaven-y-demi-action-2\",\"name\":\"Blood Boil (Recharge 4-6)\",\"description\":\"Y'demi chooses a point within 150 feet of itself, and a 20-foot radius sphere centered on that point fills with a burst of searing, blood-red mist. Each creature of Y'demi's choice that she can see in that area must make a DC 17 Constitution saving throw. On a failed save, a creature takes 38 (7d10) necrotic damage and is incapacitated until the end of its next turn. On a success, a creature takes half as much damage and isn't incapacitated. A creature dies if reduced to 0 hit points by this necrotic damage.\"}],\"bonusActions\":[{\"id\":\"strixhaven-y-demi-bonus-0\",\"name\":\"Sanguine Tentacles (1/Day)\",\"description\":\"The blood in the copper basin disappears as tentacles of congealed blood fill a 10-foot cube centered at a point on the ground that Y'demi can see within 15 feet of her. The effect lasts for 1 minute, during which time that area is 3. Any creature entering that area for the first time on a turn or starting its turn there must succeed on a DC 13 Dexterity saving throw or be restrained by the tentacles. A creature that starts its turn restrained by the tentacles takes 10 (3d6) bludgeoning damage. A creature restrained by the tentacles can use its action to make either a DC 13 Strength (Athletics) check or a DC 13 Dexterity (Acrobatics) check, ending the restrained condition on itself on a success.\"}],\"reactions\":[],\"legendaryActions\":[],\"languages\":[\"Common plus any four languages\"],\"source\":\"Strixhaven: A Curriculum of Chaos\",\"sourceId\":\"strixhaven\"}],\"ua\":[]},\"note\":\"Converted from 5etools JSON filtered to source \\\"SCC\\\".\",\"notes\":[\"Converted from 5etools JSON filtered to source \\\"SCC\\\".\"],\"documents\":[],\"sections\":[],\"meta\":{\"origin\":\"imported-json\",\"importedAt\":\"2026-10-14T17:54:20.944Z\",\"parser\":\"5etools-adapter\",\"visibility\":\"private\"}}");

